package main

import (
	"sort"
	"strings"
	"unicode"
	"unicode/utf8"
)

// adaptKinds are the in-memory rewrites --adapt counts. Nothing here is written back to the
// test262 checkout. A rewrite that would change meaning is not applied: the test stays as written,
// and the refusal stays a fact about Adamic rather than about test262's spelling.
const (
	adaptVarToLet      = "var-to-let"
	adaptCallbackParam = "callback-param"
	adaptStrictEq      = "strict-eq"
	adaptThrowError    = "throw-error"
)

// adapted is one test body after --adapt, plus how many times each rewrite fired.
type adapted struct {
	Source string
	Counts map[string]int
}

// adaptSource rewrites a test body. If the body uses syntax the scan does not understand, the body
// comes back unchanged: a partial edit from a confused scan would be a meaning change we did not prove.
func adaptSource(source string) adapted {
	parsed := parseBody(source)
	if parsed.failed {
		return adapted{Source: source}
	}
	parsed.finish()
	if parsed.failed || len(parsed.edits) == 0 {
		return adapted{Source: source}
	}
	return adapted{Source: applyEdits(source, parsed.edits), Counts: parsed.counts}
}

type edit struct {
	start int
	end   int
	text  string
}

func applyEdits(source string, edits []edit) string {
	sort.Slice(edits, func(i int, j int) bool { return edits[i].start < edits[j].start })
	for index := len(edits) - 1; index >= 0; index-- {
		change := edits[index]
		source = source[:change.start] + change.text + source[change.end:]
	}
	return source
}

type token struct {
	kind          string
	text          string
	start         int
	end           int
	newlineBefore bool
}

func tokenize(source string) []token {
	var tokens []token
	lineStart := true
	for index := 0; index < len(source); {
		character := source[index]
		if character == ' ' || character == '\t' || character == '\r' || character == '\n' {
			if character == '\n' {
				lineStart = true
			}
			index++
			continue
		}
		if character == '/' && index+1 < len(source) && source[index+1] == '/' {
			end := strings.IndexByte(source[index:], '\n')
			if end < 0 {
				break
			}
			index += end
			continue
		}
		if character == '/' && index+1 < len(source) && source[index+1] == '*' {
			end := strings.Index(source[index+2:], "*/")
			if end < 0 {
				return nil
			}
			if strings.Contains(source[index:index+2+end+2], "\n") {
				lineStart = true
			}
			index += 2 + end + 2
			continue
		}
		newline := lineStart
		lineStart = false
		if character == '\'' || character == '"' {
			end := endOfString(source, index)
			tokens = append(tokens, token{kind: "str", text: source[index:end], start: index, end: end, newlineBefore: newline})
			index = end
			continue
		}
		if character == '`' {
			end := endOfTemplate(source, index)
			if end < 0 {
				return nil
			}
			tokens = append(tokens, token{kind: "tmpl", text: source[index:end], start: index, end: end, newlineBefore: newline})
			index = end
			continue
		}
		if character == '/' && allowsRegex(tokens) {
			end := endOfRegex(source, index)
			if end < 0 {
				return nil
			}
			tokens = append(tokens, token{kind: "regexp", text: source[index:end], start: index, end: end, newlineBefore: newline})
			index = end
			continue
		}
		if isDigit(character) || (character == '.' && index+1 < len(source) && isDigit(source[index+1])) {
			end := endOfNumber(source, index)
			tokens = append(tokens, token{kind: "num", text: source[index:end], start: index, end: end, newlineBefore: newline})
			index = end
			continue
		}
		runeValue, size := utf8.DecodeRuneInString(source[index:])
		if isIdentifierStart(runeValue) || (runeValue >= 0x80 && unicode.IsLetter(runeValue)) {
			end := endOfIdent(source, index)
			tokens = append(tokens, token{kind: "ident", text: source[index:end], start: index, end: end, newlineBefore: newline})
			index = end
			continue
		}
		_ = size
		end := index + 1
		if index+2 < len(source) {
			three := source[index : index+3]
			if three == "===" || three == "!==" || three == ">>>" || three == "..." {
				end = index + 3
			}
		}
		if end == index+1 && index+1 < len(source) {
			two := source[index : index+2]
			switch two {
			case "==", "!=", "<=", ">=", "=>", "++", "--", "&&", "||", "??", "+=", "-=", "*=", "/=",
				"%=", "&=", "|=", "^=", "**", "?.", "<<", ">>":
				end = index + 2
			}
		}
		tokens = append(tokens, token{kind: "punct", text: source[index:end], start: index, end: end, newlineBefore: newline})
		index = end
	}
	return tokens
}

func allowsRegex(tokens []token) bool {
	if len(tokens) == 0 {
		return true
	}
	previous := tokens[len(tokens)-1]
	switch previous.kind {
	case "num", "str", "regexp", "tmpl":
		return false
	case "ident":
		switch previous.text {
		case "return", "throw", "case", "else", "do", "typeof", "void", "in", "of", "new",
			"delete", "yield", "await", "instanceof", "extends":
			return true
		default:
			return false
		}
	}
	switch previous.text {
	case ")", "]", "}", "++", "--":
		return false
	default:
		return true
	}
}

func endOfRegex(source string, index int) int {
	index++
	inClass := false
	for index < len(source) {
		character := source[index]
		if character == '\\' && index+1 < len(source) {
			index += 2
			continue
		}
		if character == '[' {
			inClass = true
		} else if character == ']' {
			inClass = false
		} else if character == '/' && !inClass {
			index++
			for index < len(source) && isIdentByte(source[index]) {
				index++
			}
			return index
		} else if character == '\n' {
			return -1
		}
		index++
	}
	return -1
}

func endOfTemplate(source string, index int) int {
	index++
	for index < len(source) {
		if source[index] == '\\' && index+1 < len(source) {
			index += 2
			continue
		}
		if source[index] == '`' {
			return index + 1
		}
		if source[index] == '$' && index+1 < len(source) && source[index+1] == '{' {
			_, next, ok := expressionInside(source, index+2, 1)
			if !ok {
				return -1
			}
			index = next
			continue
		}
		index++
	}
	return -1
}

func endOfNumber(source string, index int) int {
	if source[index] == '0' && index+1 < len(source) {
		switch source[index+1] {
		case 'x', 'X', 'b', 'B', 'o', 'O':
			index += 2
			for index < len(source) && (isHex(source[index]) || source[index] == '_') {
				index++
			}
			return index
		}
	}
	sawDigit := false
	for index < len(source) && (isDigit(source[index]) || source[index] == '_') {
		if isDigit(source[index]) {
			sawDigit = true
		}
		index++
	}
	if index < len(source) && source[index] == '.' {
		index++
		for index < len(source) && (isDigit(source[index]) || source[index] == '_') {
			if isDigit(source[index]) {
				sawDigit = true
			}
			index++
		}
	}
	if !sawDigit {
		return index
	}
	if index < len(source) && (source[index] == 'e' || source[index] == 'E') {
		next := index + 1
		if next < len(source) && (source[next] == '+' || source[next] == '-') {
			next++
		}
		if next < len(source) && isDigit(source[next]) {
			index = next + 1
			for index < len(source) && isDigit(source[index]) {
				index++
			}
		}
	}
	if index < len(source) && (source[index] == 'n') {
		index++
	}
	return index
}

func endOfIdent(source string, index int) int {
	for index < len(source) {
		runeValue, size := utf8.DecodeRuneInString(source[index:])
		if runeValue < 0x80 && !isIdentifierPart(runeValue) {
			break
		}
		if runeValue >= 0x80 && !unicode.IsLetter(runeValue) && !unicode.IsDigit(runeValue) && runeValue != '_' && runeValue != '$' {
			break
		}
		index += size
	}
	return index
}

func isDigit(character byte) bool { return character >= '0' && character <= '9' }
func isHex(character byte) bool {
	return isDigit(character) || (character >= 'a' && character <= 'f') || (character >= 'A' && character <= 'F')
}
func isIdentByte(character byte) bool { return isIdentifierPart(rune(character)) }

// jtype is a type the scan proved. A nil type is unknown, and unknown is never annotated and
// never used to justify rewriting ==.
type jtype struct {
	kind   string
	elem   *jtype
	fields []jfield
}

type jfield struct {
	name string
	typ  *jtype
}

func (kind *jtype) string() string {
	if kind == nil {
		return ""
	}
	switch kind.kind {
	case "number", "string", "boolean", "undefined", "null":
		return kind.kind
	case "array":
		inner := kind.elem.string()
		if inner == "" {
			return ""
		}
		if strings.Contains(inner, " ") {
			return "(" + inner + ")[]"
		}
		return inner + "[]"
	case "object":
		if len(kind.fields) == 0 {
			return ""
		}
		parts := make([]string, 0, len(kind.fields))
		for _, field := range kind.fields {
			rendered := field.typ.string()
			if rendered == "" || !identText(field.name) {
				return ""
			}
			parts = append(parts, field.name+": "+rendered)
		}
		return "{ " + strings.Join(parts, ", ") + " }"
	case "union":
		return ""
	default:
		return ""
	}
}

func identText(name string) bool {
	if name == "" {
		return false
	}
	first, _ := utf8.DecodeRuneInString(name)
	if !isIdentifierStart(first) {
		return false
	}
	for _, character := range name {
		if !isIdentifierPart(character) {
			return false
		}
	}
	return true
}

func sameType(left *jtype, right *jtype) bool {
	if left == nil || right == nil || left.kind != right.kind {
		return false
	}
	switch left.kind {
	case "number", "string", "boolean", "undefined", "null":
		return true
	case "array":
		return sameType(left.elem, right.elem)
	case "object":
		if len(left.fields) != len(right.fields) {
			return false
		}
		for index := range left.fields {
			if left.fields[index].name != right.fields[index].name || !sameType(left.fields[index].typ, right.fields[index].typ) {
				return false
			}
		}
		return true
	default:
		return false
	}
}

// strictEqualOK reports whether == and === agree on every value of these two types.
// The same primitive does not coerce. Two objects compare by reference either way.
// null compared with undefined does coerce, and that pair is not the same kind, so it stays.
func strictEqualOK(left *jtype, right *jtype) bool {
	if left == nil || right == nil || left.kind != right.kind {
		return false
	}
	switch left.kind {
	case "number", "string", "boolean", "null", "undefined", "object", "array":
		return true
	default:
		return false
	}
}

var (
	typeNumber    = &jtype{kind: "number"}
	typeString    = &jtype{kind: "string"}
	typeBoolean   = &jtype{kind: "boolean"}
	typeUndefined = &jtype{kind: "undefined"}
	typeNull      = &jtype{kind: "null"}
)

func arrayOf(elem *jtype) *jtype {
	if elem == nil {
		return nil
	}
	return &jtype{kind: "array", elem: elem}
}

type texpr struct {
	op        string
	name      string
	prop      string
	scope     *scope
	fn        *fnInfo
	left      *texpr
	right     *texpr
	elems     []*texpr
	fields    []namedExpr
	arrayCtor bool
}

type namedExpr struct {
	name string
	expr *texpr
}

type binding struct {
	kind     string
	name     string
	fn       *fnInfo
	init     *texpr
	assigns  []assignNote
	typ      *jtype
	poison   bool
	visiting bool
}

type assignNote struct {
	rhs *texpr
	inc bool
}

type fnInfo struct {
	params []param
	scope  *scope
}

type param struct {
	name       string
	nameEnd    int
	typed      bool
	rest       bool
	pattern    bool
	hasDefault bool
}

type scope struct {
	kind   string
	parent *scope
	fn     *scope
	loop   *scope
	start  int
	end    int
	names  map[string]*binding
}

type reference struct {
	name   string
	scope  *scope
	at     int
	inInit *binding
}

type varDecl struct {
	name    string
	binding *binding
	nameAt  int
	block   *scope
	fn      *scope
	loop    *scope
	loopVar bool
	stmt    *varStmt
	unsafe  bool
}

type varStmt struct {
	keyword token
	decls   []*varDecl
}

type callNote struct {
	method  string
	recv    *texpr
	args    []*texpr
	viaCall bool
}

type cmpNote struct {
	op    string
	start int
	end   int
	left  *texpr
	right *texpr
}

type throwNote struct {
	start int
	end   int
}

type lateAssign struct {
	name  string
	scope *scope
	note  assignNote
}

type parser struct {
	toks              []token
	pos               int
	scope             *scope
	failed            bool
	unsafeVars        bool
	edits             []edit
	counts            map[string]int
	refs              []reference
	varStmts          []*varStmt
	calls             []callNote
	cmps              []cmpNote
	throws            []throwNote
	lateAssigns       []lateAssign
	initializing      *binding
	instanceOfTest262 bool
}

func parseBody(source string) *parser {
	parsed := &parser{toks: tokenize(source), counts: map[string]int{}}
	if parsed.toks == nil && strings.TrimSpace(source) != "" {
		parsed.failed = true
		return parsed
	}
	for index := 0; index+1 < len(parsed.toks); index++ {
		if parsed.toks[index].text == "instanceof" && parsed.toks[index+1].text == "Test262Error" {
			parsed.instanceOfTest262 = true
		}
	}
	parsed.scope = &scope{kind: "module", names: map[string]*binding{}, start: 0}
	parsed.scope.fn = parsed.scope
	parsed.parseStatements(true)
	if parsed.scope != nil && parsed.scope.kind == "module" {
		parsed.scope.end = len(parsed.toks)
	}
	if !parsed.failed && parsed.pos < len(parsed.toks) {
		parsed.failed = true
	}
	return parsed
}

func (p *parser) peek() token {
	if p.pos >= len(p.toks) {
		return token{kind: "eof", text: "eof"}
	}
	return p.toks[p.pos]
}

func (p *parser) eof() bool { return p.pos >= len(p.toks) }

func (p *parser) next() token {
	tok := p.peek()
	if p.pos < len(p.toks) {
		p.pos++
	}
	return tok
}

func (p *parser) is(text string) bool { return p.peek().text == text }

func (p *parser) fail() { p.failed = true }

func (p *parser) expect(text string) {
	if p.failed {
		return
	}
	if !p.is(text) {
		p.fail()
		return
	}
	p.next()
}

func (p *parser) parseStatements(top bool) {
	for !p.failed && !p.eof() {
		if !top && p.is("}") {
			return
		}
		before := p.pos
		p.parseStatement()
		if p.pos == before {
			p.fail()
			return
		}
	}
}

func (p *parser) parseStatement() {
	if p.failed || p.eof() {
		return
	}
	switch p.peek().text {
	case ";":
		p.next()
		return
	case "{":
		p.parseBlock()
		return
	case "var", "let", "const":
		p.parseDeclaration(false)
		p.semi()
		return
	case "function":
		p.parseFunction(true)
		return
	case "class":
		p.skipBraced()
		p.unsafeVars = true
		return
	case "if":
		p.next()
		p.expect("(")
		p.parseSequence(false)
		p.expect(")")
		p.parseControlled()
		if p.is("else") {
			p.next()
			p.parseControlled()
		}
		return
	case "for":
		p.parseFor()
		return
	case "while":
		p.next()
		loop := p.push("loop")
		p.expect("(")
		p.parseSequence(false)
		p.expect(")")
		p.parseControlled()
		p.pop(loop)
		return
	case "do":
		p.next()
		loop := p.push("loop")
		p.parseControlled()
		p.expect("while")
		p.expect("(")
		p.parseSequence(false)
		p.expect(")")
		p.semi()
		p.pop(loop)
		return
	case "switch":
		p.parseSwitch()
		return
	case "try":
		p.parseTry()
		return
	case "throw":
		p.parseThrow()
		return
	case "return":
		p.next()
		if !p.eof() && !p.is("}") && !p.is(";") && !p.peek().newlineBefore {
			p.parseSequence(false)
		}
		p.semi()
		return
	case "break", "continue", "debugger":
		p.next()
		if p.peek().kind == "ident" && !isKeyword(p.peek().text) && !p.peek().newlineBefore && !p.is(";") && !p.is("}") {
			p.next()
		}
		p.semi()
		return
	case "import", "export", "with":
		p.fail()
		return
	}
	if p.peek().kind == "ident" && !isKeyword(p.peek().text) && p.pos+1 < len(p.toks) && p.toks[p.pos+1].text == ":" {
		p.next()
		p.next()
		p.parseStatement()
		return
	}
	if p.peek().text == "async" && p.pos+1 < len(p.toks) && p.toks[p.pos+1].text == "function" {
		p.fail()
		return
	}
	p.parseSequence(false)
	p.semi()
}

func (p *parser) parseControlled() {
	block := p.push("block")
	p.parseStatement()
	p.pop(block)
}

func (p *parser) parseBlock() {
	p.expect("{")
	block := p.push("block")
	p.parseStatements(false)
	p.pop(block)
	p.expect("}")
}

func (p *parser) push(kind string) *scope {
	child := &scope{
		kind:   kind,
		parent: p.scope,
		names:  map[string]*binding{},
		start:  p.pos,
		fn:     p.scope.fn,
		loop:   p.scope.loop,
	}
	if kind == "func" {
		child.fn = child
		child.loop = nil
	}
	if kind == "loop" {
		child.loop = child
	}
	p.scope = child
	return child
}

func (p *parser) pop(child *scope) {
	child.end = p.pos
	if p.scope == child {
		p.scope = child.parent
	}
}

func (p *parser) semi() {
	if p.failed {
		return
	}
	if p.is(";") {
		p.next()
		return
	}
	if p.eof() || p.is("}") || p.peek().newlineBefore {
		return
	}
	p.fail()
}

func (p *parser) parseDeclaration(forHeader bool) {
	keyword := p.next()
	stmt := &varStmt{keyword: keyword}
	for !p.failed {
		if p.peek().kind != "ident" || isKeyword(p.peek().text) {
			p.fail()
			return
		}
		nameTok := p.next()
		binding := &binding{kind: keyword.text, name: nameTok.text}
		decl := &varDecl{
			name:    nameTok.text,
			binding: binding,
			nameAt:  p.pos - 1,
			block:   p.scope,
			fn:      p.scope.fn,
			loop:    p.scope.loop,
			loopVar: forHeader && keyword.text == "var",
			stmt:    stmt,
		}
		if keyword.text == "var" {
			existing := p.scope.fn.names[nameTok.text]
			if existing == nil {
				p.scope.fn.names[nameTok.text] = binding
			} else if existing.kind == "var" {
				existing.poison = true
				decl.binding = existing
				binding = existing
			} else {
				decl.unsafe = true
			}
		} else if _, exists := p.scope.names[nameTok.text]; exists {
			binding.poison = true
			p.scope.names[nameTok.text] = binding
		} else {
			p.scope.names[nameTok.text] = binding
		}
		if p.is("=") {
			p.next()
			saved := p.initializing
			p.initializing = binding
			binding.init = p.parseAssign(forHeader)
			p.initializing = saved
			if binding.init != nil && binding.init.op == "fn" && binding.fn == nil {
				binding.fn = binding.init.fn
			}
		}
		stmt.decls = append(stmt.decls, decl)
		if p.is(",") {
			p.next()
			continue
		}
		break
	}
	if keyword.text == "var" {
		p.varStmts = append(p.varStmts, stmt)
	}
}

func (p *parser) parseFor() {
	p.next()
	loop := p.push("loop")
	p.expect("(")
	switch {
	case p.is("var"), p.is("let"), p.is("const"):
		p.parseDeclaration(true)
		if p.is("in") || p.is("of") {
			p.next()
			p.parseAssign(false)
		} else {
			p.expect(";")
			if !p.is(";") {
				p.parseSequence(false)
			}
			p.expect(";")
			if !p.is(")") {
				p.parseSequence(false)
			}
		}
	case p.is(";"):
		p.next()
		if !p.is(";") {
			p.parseSequence(false)
		}
		p.expect(";")
		if !p.is(")") {
			p.parseSequence(false)
		}
	default:
		p.parseSequence(true)
		if p.is("in") || p.is("of") {
			p.next()
			p.parseAssign(false)
		} else {
			p.expect(";")
			if !p.is(";") {
				p.parseSequence(false)
			}
			p.expect(";")
			if !p.is(")") {
				p.parseSequence(false)
			}
		}
	}
	p.expect(")")
	p.parseControlled()
	p.pop(loop)
}

func (p *parser) parseSwitch() {
	p.next()
	p.expect("(")
	p.parseSequence(false)
	p.expect(")")
	p.expect("{")
	block := p.push("switch")
	for !p.failed && !p.eof() && !p.is("}") {
		if p.is("case") {
			p.next()
			p.parseSequence(false)
			p.expect(":")
			continue
		}
		if p.is("default") {
			p.next()
			p.expect(":")
			continue
		}
		before := p.pos
		p.parseStatement()
		if p.pos == before {
			p.fail()
			return
		}
	}
	p.pop(block)
	p.expect("}")
}

func (p *parser) parseTry() {
	p.next()
	p.parseBlock()
	if p.is("catch") {
		p.next()
		p.expect("(")
		catchScope := p.push("block")
		if p.peek().kind == "ident" && !isKeyword(p.peek().text) {
			name := p.next()
			catchScope.names[name.text] = &binding{kind: "catch", name: name.text, poison: true}
			if p.is("if") {
				p.fail()
				return
			}
		} else {
			p.skipBalanced(p.peek().text, matchingClose(p.peek().text))
		}
		p.expect(")")
		p.parseBlock()
		p.pop(catchScope)
	}
	if p.is("finally") {
		p.next()
		p.parseBlock()
	}
}

func (p *parser) parseThrow() {
	p.next()
	if p.peek().newlineBefore {
		p.fail()
		return
	}
	if p.is("new") && p.pos+1 < len(p.toks) && p.toks[p.pos+1].text == "Test262Error" && !p.instanceOfTest262 {
		name := p.toks[p.pos+1]
		p.throws = append(p.throws, throwNote{start: name.start, end: name.end})
	}
	p.parseSequence(false)
	p.semi()
}

func (p *parser) parseFunction(statement bool) *fnInfo {
	p.next()
	var name string
	var nameTok token
	if p.peek().kind == "ident" && !isKeyword(p.peek().text) {
		nameTok = p.next()
		name = nameTok.text
	} else if statement {
		p.fail()
		return nil
	}
	fnScope := p.push("func")
	info := &fnInfo{scope: fnScope}
	if statement && name != "" {
		binding := &binding{kind: "func", name: name, fn: info}
		parent := fnScope.parent
		if existing := parent.names[name]; existing != nil {
			existing.poison = true
			existing.fn = nil
		} else {
			parent.names[name] = binding
		}
	}
	p.parseParamList(info, fnScope)
	if p.is(":") {
		p.next()
		p.skipType()
	}
	p.expect("{")
	if !statement && name != "" {
		// The expression's own name is visible inside it, and it is not the binding a call site sees.
		fnScope.names[name] = &binding{kind: "func", name: name, poison: true}
	}
	p.parseStatements(false)
	p.expect("}")
	p.pop(fnScope)
	return info
}

func (p *parser) parseParamList(info *fnInfo, fnScope *scope) {
	p.expect("(")
	for !p.failed && !p.is(")") && !p.eof() {
		param := param{}
		if p.is("...") {
			p.next()
			param.rest = true
		}
		if p.is("{") || p.is("[") {
			param.pattern = true
			p.skipBalanced(p.peek().text, matchingClose(p.peek().text))
		} else if p.peek().kind == "ident" && !isKeyword(p.peek().text) {
			name := p.next()
			param.name = name.text
			param.nameEnd = name.end
			if p.is(":") {
				param.typed = true
				p.next()
				p.skipType()
			}
			if p.is("=") {
				param.hasDefault = true
				p.next()
				p.parseAssign(false)
			}
			if param.name != "" {
				fnScope.names[param.name] = &binding{kind: "param", name: param.name}
			}
		} else {
			p.fail()
			break
		}
		info.params = append(info.params, param)
		if p.is(",") {
			p.next()
			continue
		}
		break
	}
	p.expect(")")
}

func (p *parser) skipType() {
	depth := 0
	for !p.failed && !p.eof() {
		text := p.peek().text
		if depth == 0 && (text == "," || text == ")" || text == "=" || text == "{" || text == ";" || text == "=>") {
			return
		}
		if text == "(" || text == "{" || text == "[" || text == "<" {
			depth++
		} else if text == ")" || text == "}" || text == "]" || text == ">" {
			depth--
			if depth < 0 {
				return
			}
		}
		p.next()
	}
}

func matchingClose(open string) string {
	switch open {
	case "{":
		return "}"
	case "[":
		return "]"
	case "(":
		return ")"
	default:
		return ""
	}
}

func (p *parser) skipBalanced(open string, close string) {
	if close == "" || !p.is(open) {
		p.fail()
		return
	}
	depth := 0
	for !p.eof() {
		text := p.next().text
		if text == open {
			depth++
		} else if text == close {
			depth--
			if depth == 0 {
				return
			}
		}
	}
	p.fail()
}

func (p *parser) skipBraced() {
	for !p.failed && !p.eof() && !p.is("{") {
		switch p.peek().text {
		case "(", "[":
			open := p.peek().text
			p.skipBalanced(open, matchingClose(open))
		default:
			p.next()
		}
	}
	p.skipBalanced("{", "}")
}

func (p *parser) parseSequence(noIn bool) *texpr {
	expr := p.parseAssign(noIn)
	for p.is(",") && !p.failed {
		p.next()
		expr = p.parseAssign(noIn)
	}
	return expr
}

func (p *parser) parseAssign(noIn bool) *texpr {
	left := p.parseConditional(noIn)
	if p.failed || left == nil {
		return left
	}
	op := p.peek().text
	if op == "=" || op == "+=" || op == "-=" || op == "*=" || op == "/=" || op == "%=" {
		p.next()
		right := p.parseAssign(noIn)
		if left.op == "name" {
			note := assignNote{rhs: right}
			if op != "=" {
				note.rhs = &texpr{op: "unknown"}
				note.inc = false
			}
			if binding := lookup(left.scope, left.name); binding != nil {
				binding.assigns = append(binding.assigns, note)
			} else {
				p.lateAssigns = append(p.lateAssigns, lateAssign{name: left.name, scope: left.scope, note: note})
			}
		}
		if op == "=" {
			return right
		}
		return &texpr{op: "unknown"}
	}
	return left
}

func (p *parser) parseConditional(noIn bool) *texpr {
	expr := p.parseBinary(noIn, 1)
	if !p.is("?") {
		return expr
	}
	p.next()
	yes := p.parseAssign(false)
	p.expect(":")
	no := p.parseAssign(noIn)
	return &texpr{op: "ternary", left: yes, right: no, elems: []*texpr{expr}}
}

func (p *parser) parseBinary(noIn bool, min int) *texpr {
	left := p.parseUnary()
	for !p.failed {
		op := p.peek()
		prec := precedence(op.text, noIn)
		if prec < min {
			break
		}
		p.next()
		right := p.parseBinary(noIn, prec+1)
		if (op.text == "==" || op.text == "!=") && left != nil && right != nil {
			p.cmps = append(p.cmps, cmpNote{op: op.text, start: op.start, end: op.end, left: left, right: right})
		}
		kind := "unknown"
		switch op.text {
		case "==", "!=", "===", "!==", "<", ">", "<=", ">=", "instanceof", "in":
			kind = "bool"
		case "+":
			kind = "add"
		case "-":
			kind = "sub"
		case "*", "/", "%":
			kind = "mul"
		case "&&", "||", "??":
			kind = "logic"
		}
		left = &texpr{op: kind, left: left, right: right}
	}
	return left
}

func precedence(op string, noIn bool) int {
	switch op {
	case "??":
		return 1
	case "||":
		return 2
	case "&&":
		return 3
	case "==", "!=", "===", "!==":
		return 4
	case "<", ">", "<=", ">=", "instanceof":
		return 5
	case "in":
		if noIn {
			return 0
		}
		return 5
	case "<<", ">>", ">>>":
		return 6
	case "+", "-":
		return 7
	case "*", "/", "%":
		return 8
	default:
		return 0
	}
}

func (p *parser) parseUnary() *texpr {
	switch p.peek().text {
	case "++", "--":
		p.next()
		operand := p.parseUnary()
		p.noteInc(operand)
		return &texpr{op: "inc", left: operand}
	case "+", "-", "!", "~", "typeof", "void", "delete":
		op := p.next().text
		operand := p.parseUnary()
		switch op {
		case "typeof":
			return &texpr{op: "typeof", left: operand}
		case "void":
			return &texpr{op: "void"}
		case "!":
			return &texpr{op: "bool"}
		case "+":
			return &texpr{op: "num"}
		case "-":
			if operand != nil && operand.op == "num" {
				return operand
			}
			return &texpr{op: "num", left: operand}
		default:
			return &texpr{op: "unknown"}
		}
	case "await", "yield":
		p.fail()
		return nil
	}
	return p.parsePostfix()
}

func (p *parser) noteInc(operand *texpr) {
	if operand == nil || operand.op != "name" {
		return
	}
	note := assignNote{inc: true}
	if binding := lookup(operand.scope, operand.name); binding != nil {
		binding.assigns = append(binding.assigns, note)
	} else {
		p.lateAssigns = append(p.lateAssigns, lateAssign{name: operand.name, scope: operand.scope, note: note})
	}
}

func (p *parser) parsePostfix() *texpr {
	expr := p.parsePrimary()
	for !p.failed && expr != nil {
		switch {
		case p.is(".") || p.is("?."):
			optional := p.next().text == "?."
			if optional && p.is("(") {
				p.parseCall(&texpr{op: "unknown"})
				expr = &texpr{op: "unknown"}
				continue
			}
			name := p.peek()
			if name.kind != "ident" {
				p.fail()
				return expr
			}
			p.next()
			expr = &texpr{op: "member", prop: name.text, left: expr}
		case p.is("("):
			if expr.op == "name" && expr.name == "Array" {
				call := p.finishCall(expr)
				expr = &texpr{op: "array", elems: call, arrayCtor: true}
				continue
			}
			expr = p.parseCall(expr)
		case p.is("["):
			p.next()
			p.parseSequence(false)
			p.expect("]")
			expr = &texpr{op: "index", left: expr}
		case (p.is("++") || p.is("--")) && !p.peek().newlineBefore:
			p.noteInc(expr)
			p.next()
			expr = &texpr{op: "inc", left: expr}
		default:
			return expr
		}
	}
	return expr
}

func (p *parser) parseCall(callee *texpr) *texpr {
	args := p.finishCall(callee)
	p.noteCall(callee, args)
	return &texpr{op: "call", left: callee, elems: args}
}

func (p *parser) finishCall(callee *texpr) []*texpr {
	p.expect("(")
	var args []*texpr
	for !p.failed && !p.is(")") && !p.eof() {
		if p.is("...") {
			p.next()
			p.parseAssign(false)
			args = append(args, &texpr{op: "unknown"})
		} else {
			args = append(args, p.parseAssign(false))
		}
		if p.is(",") {
			p.next()
			continue
		}
		break
	}
	p.expect(")")
	_ = callee
	return args
}

func (p *parser) noteCall(callee *texpr, args []*texpr) {
	if callee == nil || callee.op != "member" {
		return
	}
	if callee.prop == "call" && callee.left != nil && callee.left.op == "member" && callbackMethod(callee.left.prop) {
		p.calls = append(p.calls, callNote{method: callee.left.prop, recv: callee.left.left, args: args, viaCall: true})
		return
	}
	if callbackMethod(callee.prop) {
		p.calls = append(p.calls, callNote{method: callee.prop, recv: callee.left, args: args})
	}
}

func callbackMethod(name string) bool {
	switch name {
	case "forEach", "map", "filter", "every", "some", "find", "findIndex", "findLast", "findLastIndex",
		"flatMap", "sort", "reduce", "reduceRight", "replace", "replaceAll":
		return true
	default:
		return false
	}
}

func (p *parser) parsePrimary() *texpr {
	tok := p.peek()
	switch tok.kind {
	case "num":
		p.next()
		if strings.HasSuffix(tok.text, "n") {
			return &texpr{op: "unknown"}
		}
		return &texpr{op: "num"}
	case "str":
		p.next()
		return &texpr{op: "str"}
	case "regexp":
		p.next()
		return &texpr{op: "unknown"}
	case "tmpl":
		p.next()
		if strings.Contains(tok.text, "${") {
			// A template can close over a var. Missing that reference would make var to let a lie,
			// so the whole file keeps its vars. The template text itself is not rewritten.
			p.unsafeVars = true
		}
		return &texpr{op: "str"}
	}
	switch tok.text {
	case "[":
		return p.parseArray()
	case "{":
		return p.parseObject()
	case "function":
		return &texpr{op: "fn", fn: p.parseFunction(false)}
	case "new":
		return p.parseNew()
	case "(":
		if p.looksArrow() {
			return p.parseArrow()
		}
		p.next()
		expr := p.parseSequence(false)
		p.expect(")")
		return expr
	case "ident":
		return p.parseIdent()
	}
	if tok.kind == "ident" {
		return p.parseIdent()
	}
	p.fail()
	return nil
}

func (p *parser) parseNew() *texpr {
	p.next()
	expr := p.parsePostfix()
	if expr != nil && expr.arrayCtor {
		return expr
	}
	if expr != nil && expr.op == "call" && expr.left != nil && expr.left.op == "name" && expr.left.name == "Array" {
		return &texpr{op: "array", elems: expr.elems, arrayCtor: true}
	}
	return &texpr{op: "unknown"}
}

func (p *parser) parseIdent() *texpr {
	tok := p.next()
	switch tok.text {
	case "true", "false":
		return &texpr{op: "bool"}
	case "null":
		return &texpr{op: "null"}
	case "undefined":
		if lookup(p.scope, "undefined") == nil {
			return &texpr{op: "undefined"}
		}
	case "NaN", "Infinity":
		if lookup(p.scope, tok.text) == nil {
			return &texpr{op: "num"}
		}
	}
	if isKeyword(tok.text) {
		p.fail()
		return nil
	}
	if p.is("=>") {
		fnScope := p.push("func")
		fnScope.names[tok.text] = &binding{kind: "param", name: tok.text}
		return p.finishArrow([]param{{name: tok.text, nameEnd: tok.end}}, fnScope)
	}
	resolved := lookup(p.scope, tok.text)
	inInit := p.initializing
	if resolved == nil || resolved != p.initializing {
		inInit = nil
	}
	p.refs = append(p.refs, reference{name: tok.text, scope: p.scope, at: p.pos - 1, inInit: inInit})
	return &texpr{op: "name", name: tok.text, scope: p.scope}
}

func (p *parser) parseArray() *texpr {
	p.expect("[")
	var elems []*texpr
	hole := false
	for !p.failed && !p.is("]") && !p.eof() {
		if p.is(",") {
			hole = true
			p.next()
			continue
		}
		if p.is("...") {
			p.next()
			p.parseAssign(false)
			hole = true
		} else {
			elems = append(elems, p.parseAssign(false))
		}
		if p.is(",") {
			p.next()
			continue
		}
		break
	}
	p.expect("]")
	if hole {
		return &texpr{op: "unknown"}
	}
	return &texpr{op: "array", elems: elems}
}

func (p *parser) parseObject() *texpr {
	p.expect("{")
	var fields []namedExpr
	pure := true
	for !p.failed && !p.is("}") && !p.eof() {
		if p.is("...") {
			p.next()
			p.parseAssign(false)
			pure = false
		} else if p.is("[") {
			p.skipBalanced("[", "]")
			p.parseMethodTail(true)
			pure = false
		} else if p.peek().kind == "ident" || p.peek().kind == "str" || p.peek().kind == "num" {
			key := p.next()
			name := key.text
			if key.kind == "str" && len(name) >= 2 {
				name = name[1 : len(name)-1]
			}
			if isModifier(key.text) && (p.peek().kind == "ident" || p.peek().kind == "str" || p.is("[")) {
				pure = false
				if p.is("[") {
					p.skipBalanced("[", "]")
				} else {
					p.next()
				}
				p.parseMethodTail(true)
			} else if p.is("(") {
				p.parseMethodTail(false)
				pure = false
			} else if p.is(":") {
				p.next()
				fields = append(fields, namedExpr{name: name, expr: p.parseAssign(false)})
			} else if (p.is(",") || p.is("}")) && key.kind == "ident" && !isKeyword(key.text) {
				fields = append(fields, namedExpr{name: name, expr: &texpr{op: "name", name: name, scope: p.scope}})
				resolved := lookup(p.scope, name)
				inInit := p.initializing
				if resolved != p.initializing {
					inInit = nil
				}
				p.refs = append(p.refs, reference{name: name, scope: p.scope, at: p.pos - 1, inInit: inInit})
			} else {
				p.fail()
				return nil
			}
		} else {
			p.fail()
			return nil
		}
		if p.is(",") {
			p.next()
			continue
		}
		break
	}
	p.expect("}")
	if !pure {
		return &texpr{op: "unknown"}
	}
	return &texpr{op: "object", fields: fields}
}

func isModifier(text string) bool {
	return text == "get" || text == "set" || text == "async" || text == "static"
}

func (p *parser) parseMethodTail(alreadyNamed bool) {
	if !alreadyNamed && !p.is("(") {
		p.fail()
		return
	}
	if !p.is("(") {
		p.fail()
		return
	}
	fnScope := p.push("func")
	info := &fnInfo{scope: fnScope}
	p.parseParamList(info, fnScope)
	p.expect("{")
	p.parseStatements(false)
	p.expect("}")
	p.pop(fnScope)
}

func (p *parser) looksArrow() bool {
	if !p.is("(") {
		return false
	}
	depth := 0
	for index := p.pos; index < len(p.toks); index++ {
		text := p.toks[index].text
		if text == "(" {
			depth++
		} else if text == ")" {
			depth--
			if depth == 0 {
				return index+1 < len(p.toks) && p.toks[index+1].text == "=>"
			}
		}
	}
	return false
}

func (p *parser) parseArrow() *texpr {
	p.next()
	fnScope := p.push("func")
	var params []param
	for !p.failed && !p.is(")") && !p.eof() {
		param := param{}
		if p.is("...") {
			p.next()
			param.rest = true
		}
		if p.is("[") || p.is("{") {
			param.pattern = true
			open := p.peek().text
			p.skipBalanced(open, matchingClose(open))
		} else if p.peek().kind == "ident" && !isKeyword(p.peek().text) {
			name := p.next()
			param.name = name.text
			param.nameEnd = name.end
			if p.is(":") {
				param.typed = true
				p.next()
				p.skipType()
			}
			if p.is("=") {
				param.hasDefault = true
				p.next()
				p.parseAssign(false)
			}
			fnScope.names[param.name] = &binding{kind: "param", name: param.name}
		} else {
			p.fail()
			break
		}
		params = append(params, param)
		if p.is(",") {
			p.next()
			continue
		}
		break
	}
	p.expect(")")
	return p.finishArrow(params, fnScope)
}

func (p *parser) finishArrow(params []param, fnScope *scope) *texpr {
	info := &fnInfo{params: params, scope: fnScope}
	p.expect("=>")
	if p.is("{") {
		p.next()
		p.parseStatements(false)
		p.expect("}")
	} else {
		p.parseAssign(false)
	}
	p.pop(fnScope)
	return &texpr{op: "fn", fn: info}
}

func isKeyword(text string) bool {
	switch text {
	case "break", "case", "catch", "class", "const", "continue", "debugger", "default", "delete",
		"do", "else", "export", "extends", "finally", "for", "function", "if", "import", "in",
		"instanceof", "let", "new", "return", "super", "switch", "this", "throw", "try", "typeof",
		"var", "void", "while", "with", "yield", "await", "enum", "true", "false", "null", "static",
		"of":
		return true
	default:
		return false
	}
}

func lookup(scope *scope, name string) *binding {
	for scope != nil {
		if binding := scope.names[name]; binding != nil {
			return binding
		}
		scope = scope.parent
	}
	return nil
}

func (p *parser) finish() {
	if p.failed {
		return
	}
	for _, late := range p.lateAssigns {
		if binding := lookup(late.scope, late.name); binding != nil {
			binding.assigns = append(binding.assigns, late.note)
		}
	}
	if !p.unsafeVars {
		p.rewriteVars()
	}
	p.annotateCallbacks()
	p.rewriteEquals()
	p.rewriteThrows()
}

func (p *parser) rewriteVars() {
	for _, stmt := range p.varStmts {
		safe := len(stmt.decls) > 0
		for _, decl := range stmt.decls {
			if !p.declSafe(decl) {
				safe = false
				break
			}
		}
		if !safe {
			continue
		}
		p.edits = append(p.edits, edit{start: stmt.keyword.start, end: stmt.keyword.end, text: "let"})
		p.counts[adaptVarToLet] += len(stmt.decls)
	}
}

func (p *parser) declSafe(decl *varDecl) bool {
	if decl.unsafe || decl.binding == nil || decl.binding.poison {
		return false
	}
	if decl.block != nil && decl.block.kind == "switch" {
		// `let` directly in a switch case is a syntax error. A brace inside the case is its own block.
		return false
	}
	decls := 0
	for _, stmt := range p.varStmts {
		for _, other := range stmt.decls {
			if other.binding == decl.binding {
				decls++
			}
		}
	}
	if decls != 1 {
		return false
	}
	for _, ref := range p.refs {
		binding := lookup(ref.scope, ref.name)
		if binding != decl.binding {
			continue
		}
		if ref.inInit == decl.binding {
			return false
		}
		// A use whose token sits before the declarator is the var/let split: var reads undefined,
		// let is in the temporal dead zone. That includes a closure written above the declarator.
		if ref.at >= 0 && ref.at < decl.nameAt {
			return false
		}
		// let is scoped to the block that holds the declarator. A read from outside that block,
		// including from a function that is not inside it, would stop seeing the binding.
		if decl.block != nil && !scopeWithin(ref.scope, decl.block) {
			return false
		}
		if p.capturedAcrossLoop(decl, ref) {
			return false
		}
	}
	return true
}

func (p *parser) capturedAcrossLoop(decl *varDecl, ref reference) bool {
	if ref.scope == nil || ref.scope.fn == decl.fn {
		return false
	}
	for scope := ref.scope; scope != nil && scope != decl.fn; scope = scope.parent {
		if scope.kind != "loop" {
			continue
		}
		if decl.loopVar && decl.loop == scope {
			return true
		}
		if decl.block != scope && scopeWithin(decl.block, scope) {
			return true
		}
	}
	return false
}

func scopeWithin(inner *scope, outer *scope) bool {
	for inner != nil {
		if inner == outer {
			return true
		}
		inner = inner.parent
	}
	return false
}

func (p *parser) annotateCallbacks() {
	groups := map[*fnInfo][][]*jtype{}
	for _, call := range p.calls {
		fn := p.callbackFn(call)
		if fn == nil {
			continue
		}
		groups[fn] = append(groups[fn], p.inferCall(call))
	}
	for fn, inferences := range groups {
		if len(inferences) == 0 {
			continue
		}
		for index, param := range fn.params {
			if param.name == "" || param.typed || param.rest || param.pattern || param.hasDefault {
				continue
			}
			var chosen *jtype
			agree := true
			for _, inference := range inferences {
				if inference == nil || index >= len(inference) || inference[index] == nil {
					agree = false
					break
				}
				if chosen == nil {
					chosen = inference[index]
					continue
				}
				if !sameType(chosen, inference[index]) {
					agree = false
					break
				}
			}
			if !agree || chosen == nil {
				continue
			}
			rendered := chosen.string()
			if rendered == "" {
				continue
			}
			p.edits = append(p.edits, edit{start: param.nameEnd, end: param.nameEnd, text: ": " + rendered})
			p.counts[adaptCallbackParam]++
			if fn.scope != nil {
				if binding := fn.scope.names[param.name]; binding != nil && binding.kind == "param" {
					binding.typ = chosen
				}
			}
		}
	}
}

func (p *parser) callbackFn(call callNote) *fnInfo {
	index := 0
	if call.method == "replace" || call.method == "replaceAll" {
		index = 1
	}
	if call.viaCall {
		index++
	}
	if index >= len(call.args) || call.args[index] == nil || call.args[index].op != "name" {
		return nil
	}
	arg := call.args[index]
	binding := lookup(arg.scope, arg.name)
	if binding == nil || binding.fn == nil || binding.poison {
		return nil
	}
	return binding.fn
}

func (p *parser) inferCall(call callNote) []*jtype {
	if call.method == "replace" || call.method == "replaceAll" {
		return []*jtype{typeString}
	}
	elem := p.receiverElem(call)
	if elem == nil {
		return nil
	}
	numberAndArray := []*jtype{typeNumber, arrayOf(elem)}
	switch call.method {
	case "sort":
		return []*jtype{elem, elem}
	case "reduce", "reduceRight":
		initIndex := 1
		if call.viaCall {
			initIndex = 2
		}
		if len(call.args) > initIndex {
			initType := p.eval(call.args[initIndex])
			if initType == nil {
				return nil
			}
			return append([]*jtype{initType, elem}, numberAndArray...)
		}
		return append([]*jtype{elem, elem}, numberAndArray...)
	default:
		return append([]*jtype{elem}, numberAndArray...)
	}
}

func (p *parser) receiverElem(call callNote) *jtype {
	var recv *texpr
	if call.viaCall {
		if len(call.args) == 0 {
			return nil
		}
		recv = call.args[0]
	} else {
		recv = call.recv
	}
	typ := p.eval(recv)
	if typ == nil || typ.kind != "array" || typ.elem == nil {
		return nil
	}
	return typ.elem
}

func (p *parser) rewriteEquals() {
	for _, cmp := range p.cmps {
		if !strictEqualOK(p.eval(cmp.left), p.eval(cmp.right)) {
			continue
		}
		text := "==="
		if cmp.op == "!=" {
			text = "!=="
		}
		p.edits = append(p.edits, edit{start: cmp.start, end: cmp.end, text: text})
		p.counts[adaptStrictEq]++
	}
}

func (p *parser) rewriteThrows() {
	for _, throw := range p.throws {
		p.edits = append(p.edits, edit{start: throw.start, end: throw.end, text: "Error"})
		p.counts[adaptThrowError]++
	}
}

func (p *parser) eval(expr *texpr) *jtype {
	if expr == nil {
		return nil
	}
	switch expr.op {
	case "num":
		return typeNumber
	case "str":
		return typeString
	case "bool":
		return typeBoolean
	case "null":
		return typeNull
	case "undefined", "void":
		return typeUndefined
	case "typeof":
		return typeString
	case "name":
		binding := lookup(expr.scope, expr.name)
		if binding == nil {
			if expr.name == "undefined" {
				return typeUndefined
			}
			return nil
		}
		return p.bindingType(binding)
	case "array":
		return p.evalArray(expr)
	case "object":
		return p.evalObject(expr)
	case "member":
		if expr.prop == "length" {
			recv := p.eval(expr.left)
			if recv != nil && (recv.kind == "array" || recv.kind == "string") {
				return typeNumber
			}
		}
		return nil
	case "add":
		return addType(p.eval(expr.left), p.eval(expr.right))
	case "sub", "mul":
		left := p.eval(expr.left)
		right := p.eval(expr.right)
		if left != nil && right != nil && left.kind == "number" && right.kind == "number" {
			return typeNumber
		}
		return nil
	case "inc":
		inner := p.eval(expr.left)
		if inner != nil && inner.kind == "number" {
			return typeNumber
		}
		return nil
	case "ternary":
		left := p.eval(expr.left)
		right := p.eval(expr.right)
		if sameType(left, right) {
			return left
		}
		return nil
	case "logic":
		return nil
	default:
		return nil
	}
}

func (p *parser) bindingType(binding *binding) *jtype {
	if binding == nil || binding.poison {
		return nil
	}
	if binding.kind == "param" || binding.kind == "func" || binding.kind == "catch" {
		return binding.typ
	}
	if binding.typ != nil || binding.visiting {
		return binding.typ
	}
	binding.visiting = true
	var typ *jtype
	if binding.init != nil {
		typ = p.eval(binding.init)
	}
	for _, assign := range binding.assigns {
		if assign.inc {
			if typ == nil || typ.kind != "number" {
				typ = nil
				binding.poison = true
				break
			}
			continue
		}
		rhs := p.eval(assign.rhs)
		if typ == nil {
			typ = rhs
			continue
		}
		if rhs == nil || !sameType(typ, rhs) {
			typ = nil
			binding.poison = true
			break
		}
	}
	binding.visiting = false
	if binding.poison {
		return nil
	}
	binding.typ = typ
	return typ
}

func (p *parser) evalArray(expr *texpr) *jtype {
	if expr.arrayCtor && len(expr.elems) == 1 {
		only := p.eval(expr.elems[0])
		if only != nil && only.kind == "number" {
			return nil
		}
	}
	if len(expr.elems) == 0 {
		return nil
	}
	var elem *jtype
	for _, item := range expr.elems {
		next := p.eval(item)
		if next == nil {
			return nil
		}
		if elem == nil {
			elem = next
			continue
		}
		if sameType(elem, next) {
			continue
		}
		if elem.kind == "object" || next.kind == "object" || elem.kind == "array" || next.kind == "array" {
			return nil
		}
		merged := mergeUnion(elem, next)
		if merged == nil {
			return nil
		}
		elem = merged
	}
	if elem != nil && elem.kind == "union" {
		return nil
	}
	return arrayOf(elem)
}

func mergeUnion(left *jtype, right *jtype) *jtype {
	// Mixed primitive arrays are a real lowering gap (an array of a union). Leaving the element
	// unknown means the callback stays unannotated instead of being labeled with a type stage 0
	// cannot lower, which would just move the refusal.
	_ = left
	_ = right
	return nil
}

func (p *parser) evalObject(expr *texpr) *jtype {
	if len(expr.fields) == 0 {
		return nil
	}
	seen := map[string]bool{}
	var fields []jfield
	for _, field := range expr.fields {
		if !identText(field.name) || seen[field.name] {
			return nil
		}
		seen[field.name] = true
		typ := p.eval(field.expr)
		if typ == nil || typ.string() == "" {
			return nil
		}
		fields = append(fields, jfield{name: field.name, typ: typ})
	}
	return &jtype{kind: "object", fields: fields}
}

func addType(left *jtype, right *jtype) *jtype {
	if left == nil || right == nil {
		return nil
	}
	if left.kind == "number" && right.kind == "number" {
		return typeNumber
	}
	if (left.kind == "string" || right.kind == "string") && additivePrimitive(left) && additivePrimitive(right) {
		return typeString
	}
	return nil
}

func additivePrimitive(kind *jtype) bool {
	switch kind.kind {
	case "number", "string", "boolean":
		return true
	default:
		return false
	}
}

cache.go:
package main

import (
	"crypto/sha256"
	"embed"
	"encoding/json"
	"fmt"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"runtime/debug"
	"sort"
	"strings"
	"sync"
	"syscall"
)

// Cache observations, never verdicts: decide still compares both executions on every hit.
type resultCache struct {
	directory   string
	locks       sync.Map
	nodeContext string
}

type recordedExecution struct {
	Stdout, Stderr []byte
	Exit           int
	Signal         string
	TimedOut       bool
}

func recordExecution(value execution) recordedExecution {
	return recordedExecution{[]byte(value.Stdout), []byte(value.Stderr), value.Exit, value.Signal, value.TimedOut}
}
func (value recordedExecution) execution() execution {
	return execution{string(value.Stdout), string(value.Stderr), value.Exit, value.Signal, value.TimedOut}
}

type cacheEnvelope struct {
	Key, Digest string
	Value       json.RawMessage
}

func cacheKey(parts ...string) string {
	hash := sha256.New()
	for _, part := range parts {
		fmt.Fprintf(hash, "%d:", len(part))
		hash.Write([]byte(part))
	}
	return fmt.Sprintf("%x", hash.Sum(nil))
}

func compilerResultKey(program, compiler, command, context string) string {
	return cacheKey("test262-compiler-v1", program, compiler, command, context)
}

func nodeResultKey(program, version, adaptation, command, context string) string {
	return cacheKey("test262-node-v1", program, version, adaptation, command, context)
}
func nativeResultKey(code, library, command, context string) string {
	return cacheKey("test262-native-v1", code, library, command, context)
}

func (cache *resultCache) observe(key string, execute func() (execution, bool)) execution {
	if cache == nil || os.Getenv("ADAMIC_GATE_UNCACHED") == "1" {
		value, _ := execute()
		return value
	}
	return cache.reuse(key, execute)
}

// Tests exercise disk reuse independently of the integration gate's environment bypass.
func (cache *resultCache) reuse(key string, execute func() (execution, bool)) execution {
	value, _ := cache.locks.LoadOrStore(key, &sync.Mutex{})
	lock := value.(*sync.Mutex)
	lock.Lock()
	defer lock.Unlock()
	path := filepath.Join(cache.directory, key+".json")
	if contents, err := os.ReadFile(path); err == nil {
		var envelope cacheEnvelope
		var recorded recordedExecution
		if json.Unmarshal(contents, &envelope) == nil && envelope.Key == key && envelope.Digest == cacheKey(string(envelope.Value)) && json.Unmarshal(envelope.Value, &recorded) == nil {
			return recorded.execution()
		}
	}
	result, reusable := execute()
	// Deadlines and failed starts are host observations, not reproducible program answers.
	if !reusable || result.TimedOut || (result.Exit == -1 && result.Signal == "") {
		return result
	}
	encoded, err := json.Marshal(recordExecution(result))
	if err != nil {
		return result
	}
	contents, err := json.Marshal(cacheEnvelope{key, cacheKey(string(encoded)), encoded})
	if err != nil || os.MkdirAll(cache.directory, 0700) != nil {
		return result
	}
	temporary, err := os.CreateTemp(cache.directory, ".result-")
	if err != nil {
		return result
	}
	defer os.Remove(temporary.Name())
	_, writeError := temporary.Write(contents)
	closeError := temporary.Close()
	if writeError == nil && closeError == nil {
		_ = os.Rename(temporary.Name(), path)
	}
	return result
}

func prepareCache() (*resultCache, string, string, error) {
	directory, err := os.UserCacheDir()
	if err != nil {
		return nil, "", "", err
	}
	version, err := exec.Command("node", "--version").CombinedOutput()
	if err != nil {
		return nil, "", "", fmt.Errorf("node --version: %w: %s", err, version)
	}
	parts := []string{"test262-context-v1", runtime.GOOS, runtime.GOARCH, fmt.Sprint(os.Geteuid())}
	cwd, err := os.Getwd()
	if err != nil {
		return nil, "", "", err
	}
	parts = append(parts, cwd)
	var stack syscall.Rlimit
	if err := syscall.Getrlimit(syscall.RLIMIT_STACK, &stack); err != nil {
		return nil, "", "", err
	}
	parts = append(parts, fmt.Sprint(stack.Cur, stack.Max))
	environment := os.Environ()
	sort.Strings(environment)
	for _, variable := range environment {
		if !strings.HasPrefix(variable, "ADAMIC_GATE_UNCACHED=") {
			parts = append(parts, variable)
		}
	}
	// Node's harness is embedded source plus Go build settings, not the linked compiler.
	// Lowering and the embedded runtime can change without changing Node's execution.
	nodeParts := append([]string{}, parts...)
	nodeParts = append(nodeParts, nodeHarnessIdentity())
	if info, ok := debug.ReadBuildInfo(); ok {
		nodeParts = append(nodeParts, info.GoVersion)
		for _, setting := range info.Settings {
			if !strings.HasPrefix(setting.Key, "vcs") {
				nodeParts = append(nodeParts, setting.Key, setting.Value)
			}
		}
	}
	// The full executable remains a conservative compiler and native identity.
	executable, err := os.Executable()
	if err != nil {
		return nil, "", "", err
	}
	for _, name := range []string{executable, "node", "clang"} {
		path := name
		if name != executable {
			path, err = exec.LookPath(name)
			if err != nil {
				return nil, "", "", err
			}
		}
		contents, err := os.ReadFile(path)
		if err != nil {
			return nil, "", "", err
		}
		// The runner's location is not input to successful compilation or native execution.
		// go run allocates a new executable path even for identical built bytes.
		if name == executable {
			parts = append(parts, "runner", cacheKey(string(contents)))
		} else {
			parts = append(parts, path, cacheKey(string(contents)))
		}
		if name == "node" {
			nodeParts = append(nodeParts, path, cacheKey(string(contents)))
		}
	}
	return &resultCache{directory: filepath.Join(directory, "adamic", "test262"), nodeContext: cacheKey(nodeParts...)}, string(version), cacheKey(parts...), nil
}

// Embedding the actual built sources avoids trusting mutable checkout files at run time.
// Compiler implementation and tests cannot affect the Node adaptation/capture path.
//
//go:embed *.go
var runnerSources embed.FS

func nodeHarnessIdentity() string { return nodeHarnessSourceIdentity(runnerSources) }

func nodeHarnessSourceIdentity(sources fs.FS) string {
	entries, err := fs.ReadDir(sources, ".")
	if err != nil {
		panic(err)
	}
	parts := []string{"test262-node-harness-v2"}
	for _, entry := range entries {
		name := entry.Name()
		if name == "compiler.go" || strings.HasSuffix(name, "_test.go") {
			continue
		}
		contents, err := fs.ReadFile(sources, name)
		if err != nil {
			panic(err)
		}
		parts = append(parts, name, string(contents))
	}
	return cacheKey(parts...)
}

// Binary identity covers executed compiler behavior. A source fingerprint additionally
// invalidates observations for library-worker edits that Go can elide from linked code,
// such as same-length comment changes. It only adds misses; it does not replace the binary.
func loweringSourceIdentity(root string) (string, error) {
	directory := filepath.Join(root, "internal", "lower")
	entries, err := os.ReadDir(directory)
	if err != nil {
		return "", err
	}
	parts := []string{"test262-lowering-source-v1"}
	for _, entry := range entries {
		name := entry.Name()
		if entry.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
			continue
		}
		contents, err := os.ReadFile(filepath.Join(directory, name))
		if err != nil {
			return "", err
		}
		parts = append(parts, name, string(contents))
	}
	return cacheKey(parts...), nil
}

classify.go:
package main

import (
	"regexp"
	"sort"
	"strings"
)

// harnessAdamicCanLoad is the harness files whose job the prelude does. compareArray.js is empty
// upstream (the function lives in assert.js). Anything else needs defineProperty, getters, Reflect,
// proxies, or another host the prelude does not stand in for, and the test is skipped.
var harnessAdamicCanLoad = map[string]bool{
	"assert.js":       true,
	"sta.js":          true,
	"compareArray.js": true,
}

// classified is one test, either skipped with a reason or ready to run.
type classified struct {
	Path          string
	Directory     string
	Skip          string
	NegativePhase string
	NegativeType  string
	Program       string
	Adaptations   map[string]int
}

// classify decides whether a test is attempted. Skipped tests are the ones Adamic will not learn
// from by compiling: a feature 0.1 refuses or has not built (Proxy, Symbol, eval, with, getters,
// async, and the same kind of thing), a negative parse or early error (test262's phase "parse"
// covers both, per INTERPRETING.md; an older "early" is kept), a negative resolution, or a harness
// include the prelude cannot stand in for. A missing library method is not skipped. It is attempted,
// and the refusal reason is what the library waves measure.
//
// adapt applies the in-memory test262-style rewrites (var to let, callback parameters, strict
// equality, Test262Error). It never writes the checkout. Without it, the body is only the harness
// rename the prelude needs.
func classify(path string, source string, adapt bool) classified {
	result := classified{Path: path, Directory: directoryOf(path)}
	meta := parseFrontmatter(source)
	if reason := negativeSkip(meta); reason != "" {
		result.Skip = reason
		return result
	}
	result.NegativePhase = meta.NegativePhase
	result.NegativeType = meta.NegativeType
	if reason := flagSkip(meta.Flags); reason != "" {
		result.Skip = reason
		return result
	}
	if reason := includeSkip(meta.Includes); reason != "" {
		result.Skip = reason
		return result
	}
	if reason := featureSkip(meta.Features); reason != "" {
		result.Skip = reason
		return result
	}
	body := bodyAfterFrontmatter(source)
	if reason := syntaxSkip(codeOnly(body)); reason != "" {
		result.Skip = reason
		return result
	}
	if adapt {
		rewritten := adaptSource(body)
		body = rewritten.Source
		result.Adaptations = rewritten.Counts
	}
	result.Program = program(rewriteHarnessCalls(body))
	return result
}

func directoryOf(path string) string {
	slash := strings.LastIndex(path, "/")
	if slash < 0 {
		return "."
	}
	return path[:slash]
}

func negativeSkip(meta frontmatter) string {
	switch meta.NegativePhase {
	case "", "runtime":
		// A runtime negative test is attempted. Its expectation is applied when the two runs are
		// compared, not by skipping it.
		return ""
	case "parse":
		// test262 folded early errors into phase parse. Both are "the program is not a program".
		return "negative parse or early error"
	case "early":
		return "negative early error"
	case "resolution":
		return "negative resolution"
	default:
		return "negative " + meta.NegativePhase
	}
}

func flagSkip(flags []string) string {
	for _, flag := range flags {
		switch flag {
		case "noStrict":
			return "noStrict (sloppy mode only; Adamic modules are always strict)"
		case "async":
			return "async"
		case "module":
			return "module"
		case "CanBlockIsTrue", "CanBlockIsFalse":
			return "shared memory"
		}
	}
	return ""
}

func includeSkip(includes []string) string {
	var missing []string
	for _, include := range includes {
		if !harnessAdamicCanLoad[include] {
			missing = append(missing, include)
		}
	}
	if len(missing) == 0 {
		return ""
	}
	sort.Strings(missing)
	if len(missing) == 1 {
		return "harness include " + missing[0]
	}
	return "harness includes " + strings.Join(missing, ", ")
}

func featureSkip(features []string) string {
	var refused []string
	seen := map[string]bool{}
	for _, feature := range features {
		if _, skip := unsupportedFeature(feature); skip && !seen[feature] {
			seen[feature] = true
			refused = append(refused, feature)
		}
	}
	if len(refused) == 0 {
		return ""
	}
	sort.Strings(refused)
	if len(refused) == 1 {
		return "feature " + refused[0]
	}
	return "features " + strings.Join(refused, ", ")
}

// unsupportedFeature reports whether a test262 feature is one Adamic refuses or has not built as a
// language feature, as opposed to a library method stage 0 may simply not lower yet.
func unsupportedFeature(feature string) (string, bool) {
	switch feature {
	case "Proxy", "Reflect", "Symbol", "BigInt", "generators", "async-functions",
		"async-iteration", "top-level-await", "Atomics", "SharedArrayBuffer", "ArrayBuffer",
		"resizable-arraybuffer", "TypedArray", "DataView", "cross-realm", "eval", "Temporal",
		"WeakMap", "WeakSet", "WeakRef", "FinalizationRegistry", "decorators", "import.meta",
		"dynamic-import", "json-modules", "source-phase-imports", "explicit-resource-management",
		"tail-call-optimization", "hashbang", "new.target", "with", "getters", "setters":
		return feature, true
	}
	if strings.HasPrefix(feature, "Symbol.") || strings.HasPrefix(feature, "Reflect.") {
		return feature, true
	}
	if strings.HasPrefix(feature, "regexp") || strings.HasPrefix(feature, "RegExp") {
		return feature, true
	}
	if strings.HasPrefix(feature, "async") {
		return feature, true
	}
	if strings.HasSuffix(feature, "Array") && (strings.HasPrefix(feature, "Float") || strings.HasPrefix(feature, "Int") || strings.HasPrefix(feature, "Uint") || strings.HasPrefix(feature, "Big")) {
		return feature, true
	}
	return "", false
}

var (
	syntaxEval    = regexp.MustCompile(`(?:^|[^\w$])eval\s*\(|(?:^|[^\w$])new\s+Function\b`)
	syntaxWith    = regexp.MustCompile(`(?:^|[^\w$])with\s*\(`)
	syntaxGetter  = regexp.MustCompile(`(?:^|[^\w$.])get\s+(?:[A-Za-z_$]|\[)`)
	syntaxSetter  = regexp.MustCompile(`(?:^|[^\w$.])set\s+(?:[A-Za-z_$]|\[)`)
	syntaxAsync   = regexp.MustCompile(`(?:^|[^\w$])async\s+(?:function|\()|(?:^|[^\w$])await\b`)
	syntaxYield   = regexp.MustCompile(`(?:^|[^\w$])yield\b`)
	syntaxProxy   = regexp.MustCompile(`(?:^|[^\w$])Proxy\b`)
	syntaxSymbol  = regexp.MustCompile(`(?:^|[^\w$])Symbol\b`)
	syntaxReflect = regexp.MustCompile(`(?:^|[^\w$])Reflect\b`)
	syntaxHost    = regexp.MustCompile(`(?:^|[^\w$])\$262\b`)
	syntaxBigInt  = regexp.MustCompile(`(?:^|[^\w$])BigInt\b`)
)

// syntaxSkip catches the same refusals when the test uses them without listing a feature. The scan
// sees code only, not comments or strings.
func syntaxSkip(code string) string {
	switch {
	case syntaxHost.MatchString(code):
		return "host $262"
	case syntaxEval.MatchString(code):
		return "eval"
	case syntaxWith.MatchString(code):
		return "with"
	case syntaxAsync.MatchString(code):
		return "async"
	case syntaxYield.MatchString(code):
		return "yield"
	case syntaxGetter.MatchString(code):
		return "getters"
	case syntaxSetter.MatchString(code):
		return "setters"
	case syntaxProxy.MatchString(code):
		return "Proxy"
	case syntaxSymbol.MatchString(code):
		return "Symbol"
	case syntaxReflect.MatchString(code):
		return "Reflect"
	case syntaxBigInt.MatchString(code):
		return "BigInt"
	default:
		return ""
	}
}

compiler.go:
package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"strings"
	"time"

	"github.com/system-inc/adamic/internal/load"
	"github.com/system-inc/adamic/internal/lower"
	"github.com/system-inc/adamic/internal/native"
)

// Compiler workers amortize startup without giving up the original process isolation: a hung
// checker can still be killed at the two-minute deadline. Each request owns a fresh load.Program.
func init() {
	if len(os.Args) != 2 || os.Args[1] != "--compiler-worker" {
		return
	}
	decoder := json.NewDecoder(os.Stdin)
	encoder := json.NewEncoder(os.Stdout)
	for {
		var path string
		if err := decoder.Decode(&path); err != nil {
			os.Exit(0)
		}
		if err := encoder.Encode(recordExecution(compileInProcess(path))); err != nil {
			os.Exit(1)
		}
	}
}

func compileInProcess(path string) (result execution) {
	defer func() {
		if value := recover(); value != nil {
			result = execution{Exit: 2, Stderr: fmt.Sprintf("panic: %v\n", value)}
		}
		if len(result.Stdout) > 16<<20 || len(result.Stderr) > 16<<20 {
			result = execution{Exit: -1, Stderr: "command output exceeded capture limit\n"}
		}
	}()
	loaded, err := load.Load([]string{path})
	if err != nil {
		var checkError *load.CheckError
		var diagnostic strings.Builder
		if errors.As(err, &checkError) {
			for _, text := range checkError.Diagnostics {
				fmt.Fprintln(&diagnostic, text)
			}
		} else {
			fmt.Fprintf(&diagnostic, "adamic: %v\n", err)
		}
		return execution{Exit: 1, Stderr: diagnostic.String()}
	}
	lowered, err := lower.Lower(context.Background(), loaded)
	if err != nil {
		return execution{Exit: 1, Stderr: "adamic: " + err.Error() + "\n"}
	}
	if native.UsesTSGo(lowered) {
		return execution{Exit: 1, Stderr: "adamic: tsgo requires a native build with --tsgo <archive>\n"}
	}
	code := native.C(lowered)
	if len(code) > 16<<20 {
		return execution{Exit: -1, Stderr: "command output exceeded capture limit\n"}
	}
	return execution{Stdout: code}
}

type compilerWorker struct {
	command *exec.Cmd
	input   io.WriteCloser
	output  io.ReadCloser
	encoder *json.Encoder
	decoder *json.Decoder
	timeout time.Duration
}

func (worker *compilerWorker) close() {
	if worker.command == nil {
		return
	}
	_ = worker.input.Close()
	_ = worker.output.Close()
	_ = worker.command.Process.Kill()
	_ = worker.command.Wait()
	worker.command = nil
}

func (worker *compilerWorker) compile(path string) execution {
	if worker.command == nil {
		executable, err := os.Executable()
		if err != nil {
			return execution{Exit: -1, Stderr: err.Error()}
		}
		command := exec.Command(executable, "--compiler-worker")
		input, err := command.StdinPipe()
		if err != nil {
			return execution{Exit: -1, Stderr: err.Error()}
		}
		output, err := command.StdoutPipe()
		if err != nil {
			input.Close()
			return execution{Exit: -1, Stderr: err.Error()}
		}
		if err := command.Start(); err != nil {
			input.Close()
			output.Close()
			return execution{Exit: -1, Stderr: err.Error()}
		}
		worker.command, worker.input, worker.output = command, input, output
		worker.encoder, worker.decoder = json.NewEncoder(input), json.NewDecoder(output)
	}
	done := make(chan execution, 1)
	go func() {
		if err := worker.encoder.Encode(path); err != nil {
			done <- execution{Exit: -1, Stderr: err.Error()}
			return
		}
		var result recordedExecution
		if err := worker.decoder.Decode(&result); err != nil {
			done <- execution{Exit: -1, Stderr: err.Error()}
			return
		}
		done <- result.execution()
	}()
	timeout := worker.timeout
	if timeout == 0 {
		timeout = 2 * time.Minute
	}
	timer := time.NewTimer(timeout)
	defer timer.Stop()
	select {
	case result := <-done:
		if result.Exit == -1 {
			worker.close()
		}
		return result
	case <-timer.C:
		worker.close()
		<-done
		return execution{Exit: -1, TimedOut: true}
	}
}

frontmatter.go:
package main

import (
	"strings"
	"unicode"
)

// frontmatter is the YAML between /*--- and ---*/ that test262 puts at the top of a test
// (INTERPRETING.md). Only the fields the runner acts on are kept.
type frontmatter struct {
	Features      []string
	Flags         []string
	Includes      []string
	NegativePhase string
	NegativeType  string
	Present       bool
}

// parseFrontmatter reads the first /*--- ... ---*/ block. A file without one has a zero value and
// Present false: the whole file is the test.
func parseFrontmatter(source string) frontmatter {
	start := strings.Index(source, "/*---")
	if start < 0 {
		return frontmatter{}
	}
	rest := source[start+len("/*---"):]
	end := strings.Index(rest, "---*/")
	if end < 0 {
		return frontmatter{}
	}
	parsed := parseYAMLSubset(rest[:end])
	parsed.Present = true
	return parsed
}

// bodyAfterFrontmatter is the test with that block removed. The copyright comment above it stays.
func bodyAfterFrontmatter(source string) string {
	start := strings.Index(source, "/*---")
	if start < 0 {
		return source
	}
	rest := source[start+len("/*---"):]
	end := strings.Index(rest, "---*/")
	if end < 0 {
		return source
	}
	return source[:start] + rest[end+len("---*/"):]
}

// parseYAMLSubset reads the small shape test262 actually writes: scalars, flow lists, block lists,
// and one level of nesting (negative: phase and type). Block scalars (| and >) are skipped. It is
// not a YAML parser; a construct it doesn't understand is ignored, and the test is then attempted
// rather than sorted wrong in silence only when the field was one we needed. The corpus tests cover
// the shapes this tree uses.
func parseYAMLSubset(yaml string) frontmatter {
	var parsed frontmatter
	parent := ""
	parentIndent := -1
	listKey := ""
	listIndent := -1
	blockIndent := -1
	for _, line := range strings.Split(yaml, "\n") {
		if blockIndent >= 0 {
			if strings.TrimSpace(line) == "" || indentOf(line) > blockIndent {
				continue
			}
			blockIndent = -1
		}
		if strings.TrimSpace(line) == "" {
			continue
		}
		indent := indentOf(line)
		trim := strings.TrimSpace(line)
		if strings.HasPrefix(trim, "- ") && listKey != "" && indent > listIndent {
			addField(&parsed, listKey, unquote(strings.TrimSpace(trim[2:])))
			continue
		}
		colon := strings.Index(trim, ":")
		if colon <= 0 || strings.ContainsAny(trim[:colon], " \t'\"") {
			continue
		}
		key := trim[:colon]
		value := strings.TrimSpace(trim[colon+1:])
		if parent != "" && indent <= parentIndent {
			parent = ""
		}
		fullKey := key
		if parent != "" && indent > parentIndent {
			fullKey = parent + "." + key
		}
		listKey = ""
		if value == "|" || value == ">" || value == "|-" || value == ">-" || value == "|+" || value == ">+" {
			blockIndent = indent
			continue
		}
		if value == "" {
			parent = key
			parentIndent = indent
			listKey = fullKey
			listIndent = indent
			continue
		}
		if strings.HasPrefix(value, "[") && strings.HasSuffix(value, "]") {
			for _, item := range splitFlowList(value[1 : len(value)-1]) {
				addField(&parsed, fullKey, item)
			}
			continue
		}
		setScalar(&parsed, fullKey, unquote(value))
	}
	return parsed
}

func addField(parsed *frontmatter, key string, value string) {
	if value == "" {
		return
	}
	switch key {
	case "features":
		parsed.Features = append(parsed.Features, value)
	case "flags":
		parsed.Flags = append(parsed.Flags, value)
	case "includes":
		parsed.Includes = append(parsed.Includes, value)
	default:
		setScalar(parsed, key, value)
	}
}

func setScalar(parsed *frontmatter, key string, value string) {
	switch key {
	case "negative.phase":
		parsed.NegativePhase = value
	case "negative.type":
		parsed.NegativeType = value
	case "features", "flags", "includes":
		addField(parsed, key, value)
	}
}

func splitFlowList(inside string) []string {
	if strings.TrimSpace(inside) == "" {
		return nil
	}
	parts := strings.Split(inside, ",")
	items := make([]string, 0, len(parts))
	for _, part := range parts {
		item := unquote(strings.TrimSpace(part))
		if item != "" {
			items = append(items, item)
		}
	}
	return items
}

func unquote(value string) string {
	if len(value) >= 2 {
		if (value[0] == '"' && value[len(value)-1] == '"') || (value[0] == '\'' && value[len(value)-1] == '\'') {
			return value[1 : len(value)-1]
		}
	}
	return value
}

func indentOf(line string) int {
	indent := 0
	for _, character := range line {
		if character == ' ' {
			indent++
			continue
		}
		if character == '\t' {
			indent += 2
			continue
		}
		if unicode.IsSpace(character) {
			indent++
			continue
		}
		break
	}
	return indent
}

main.go:
// Command adamic-test262 runs a slice of test262 through stage 0 and through Node, and counts how
// they compare.
//
//	adamic-test262 -test262 /path/to/test262 built-ins/String/prototype/padStart
//	adamic-test262 -adapt -json -test262 /path/to/test262 built-ins/String built-ins/Math
//
// The test262 checkout is not part of this repo: clone it at a pinned commit into a scratch
// directory and pass it. A test is skipped, with a reason, when it needs a feature Adamic refuses
// or has not built, when it is a negative parse or early error, or when it loads a harness file
// the prelude cannot stand in for. Anything else is attempted: one program, the adapted harness
// plus the test, lowered by an isolated persistent compiler worker, linked with clang and run
// natively and with Node. An explicit -root or -compiler-subprocess uses `adamic c`. pass
// means both succeeded and their output matches. fail means they disagree, or native failed where
// Node passed. refused means stage 0 or the checker said no, the reason normalized the way a meter
// groups them (cmd/adamic-meter is not on main; see reason.go). crashed means a signal, a
// sanitizer, a timeout, or the compiler itself failing. The crash record names the test file.
//
// --adapt rewrites test262's spelling in memory only, and counts each rewrite: var to let where
// the meaning does not change, a callback parameter typed the way the call would type it, == and
// != where both sides already have the same type, and throw new Test262Error to throw new Error
// when nothing observes the constructor. The checkout is not modified.
//
// -jobs defaults to GOMAXPROCS. Reports and progress lines retain serial order. The runtime is
// cached per source/toolchain/flag set, with the address and undefined-behavior sanitizers.
// Successful C generation, Node and native observations are cached under the user cache directory,
// with exact program,
// toolchain, adaptation and command identities. ADAMIC_GATE_UNCACHED=1 bypasses all result caches.
package main

import (
	"flag"
	"fmt"
	"io"
	"os"
	"runtime"
	"strings"
)

func main() {
	os.Exit(run(os.Args[1:]))
}

func run(arguments []string) (exit int) {
	flags := flag.NewFlagSet("adamic-test262", flag.ContinueOnError)
	flags.SetOutput(os.Stderr)
	test262 := flags.String("test262", "", "test262 checkout (a clone at a pinned commit, not part of this repo)")
	root := flags.String("root", ".", "Adamic checkout whose cmd/adamic and runtime are under test")
	work := flags.String("work", "", "scratch directory (default: a directory under the system temp)")
	profilePath := flags.String("profile", "", "write phase durations, cache hits and worker timeline to this JSON file")
	asJSON := flags.Bool("json", false, "write the report as JSON on stdout; the table goes to stderr")
	classifyOnly := flags.Bool("classify-only", false, "classify every test and do not compile or run")
	adapt := flags.Bool("adapt", false, "rewrite test262 style in memory (var to let, callback params, strict equality, Test262Error) and count each rewrite")
	subprocess := flags.Bool("compiler-subprocess", false, "start adamic c for each test (reference path; also used with an explicit -root)")
	jobs := flags.Int("jobs", runtime.GOMAXPROCS(0), "number of concurrent tests")
	limit := flags.Int("limit", 0, "run at most this many attempted tests per filter (0 is all)")
	flags.Usage = func() {
		fmt.Fprintf(os.Stderr, "usage: adamic-test262 [flags] <filter>...\n\n")
		fmt.Fprintf(os.Stderr, "  filter is a directory under test262's test/, like built-ins/String/prototype/padStart\n\n")
		flags.PrintDefaults()
	}
	if err := flags.Parse(arguments); err != nil {
		return 2
	}
	if *jobs < 1 {
		fmt.Fprintln(os.Stderr, "jobs must be positive")
		return 2
	}
	if *test262 == "" || flags.NArg() == 0 {
		flags.Usage()
		return 2
	}
	workDirectory := *work
	if workDirectory == "" {
		var err error
		workDirectory, err = os.MkdirTemp("", "adamic-test262-")
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			return 1
		}
	}
	var profile *runProfile
	if *profilePath != "" {
		profile = newRunProfile()
		defer func() {
			if err := profile.write(*profilePath); err != nil {
				fmt.Fprintln(os.Stderr, err)
				exit = 1
			}
		}()
	}
	inProcess := !*subprocess
	flags.Visit(func(flag *flag.Flag) {
		if flag.Name == "root" {
			inProcess = false
		}
	})
	var prepared *engine
	var err error
	if !*classifyOnly {
		prepared, err = prepareMode(*root, *test262, workDirectory, profile, inProcess)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			return 1
		}
	} else {
		prepared = &engine{test262: *test262, log: os.Stderr, adapt: *adapt}
	}
	prepared.adapt = *adapt
	prepared.jobs = *jobs
	prepared.inProcess = inProcess
	document := reportDocument{Test262: *test262, Commit: test262Commit(*test262), Adapt: *adapt}
	for _, filter := range flags.Args() {
		report, err := prepared.runFilter(filter, *limit, *classifyOnly)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			return 1
		}
		document.Filters = append(document.Filters, report)
	}
	if *asJSON {
		printTables(os.Stderr, document)
		if err := writeJSON(os.Stdout, document); err != nil {
			fmt.Fprintln(os.Stderr, err)
			return 1
		}
		return 0
	}
	printTables(os.Stdout, document)
	return 0
}

func printTables(writer io.Writer, document reportDocument) {
	if document.Commit != "" {
		fmt.Fprintf(writer, "test262 %s\n", document.Commit)
	}
	if document.Adapt {
		fmt.Fprintf(writer, "adapt on\n")
	} else {
		fmt.Fprintf(writer, "adapt off\n")
	}
	fmt.Fprintln(writer)
	for _, filter := range document.Filters {
		fmt.Fprintf(writer, "%s\n", filter.Path)
		if filter.Unrun > 0 {
			fmt.Fprintf(writer, "pass %d   fail %d   refused %d   crashed %d   skipped %d   not run %d   total %d\n\n",
				filter.Pass, filter.Fail, filter.Refused, filter.Crashed, filter.Skipped, filter.Unrun, filter.Total)
		} else {
			fmt.Fprintf(writer, "pass %d   fail %d   refused %d   crashed %d   skipped %d   total %d\n\n",
				filter.Pass, filter.Fail, filter.Refused, filter.Crashed, filter.Skipped, filter.Total)
		}
		width := len("directory")
		for _, directory := range filter.Directories {
			if len(directory.Path) > width {
				width = len(directory.Path)
			}
		}
		fmt.Fprintf(writer, "%-*s  %6s  %6s  %8s  %8s  %8s\n", width, "directory", "pass", "fail", "refused", "crashed", "skipped")
		for _, directory := range filter.Directories {
			fmt.Fprintf(writer, "%-*s  %6d  %6d  %8d  %8d  %8d\n", width, directory.Path, directory.Pass, directory.Fail, directory.Refused, directory.Crashed, directory.Skipped)
		}
		fmt.Fprintln(writer)
		printReasons(writer, "refusal reasons", filter.RefusalReasons)
		printReasons(writer, "skip reasons", filter.SkipReasons)
		printReasons(writer, "fail reasons", filter.FailReasons)
		printReasons(writer, "crash reasons", filter.CrashReasons)
		printReasons(writer, "adaptations", filter.Adaptations)
		if len(filter.Passes) > 0 {
			fmt.Fprintf(writer, "passes (%d)\n", len(filter.Passes))
			shown := filter.Passes
			if len(shown) > 40 {
				shown = shown[:40]
			}
			for _, path := range shown {
				fmt.Fprintf(writer, "  %s\n", path)
			}
			if len(filter.Passes) > len(shown) {
				fmt.Fprintf(writer, "  ... and %d more\n", len(filter.Passes)-len(shown))
			}
			fmt.Fprintln(writer)
		}
	}
}

func printReasons(writer io.Writer, title string, reasons []reasonCount) {
	if len(reasons) == 0 {
		return
	}
	fmt.Fprintf(writer, "%s\n", title)
	shown := reasons
	if len(shown) > 15 {
		shown = shown[:15]
	}
	width := 0
	for _, reason := range shown {
		if reason.Count > width {
			width = reason.Count
		}
	}
	digits := len(fmt.Sprintf("%d", width))
	for _, reason := range shown {
		fmt.Fprintf(writer, "  %*d  %s\n", digits, reason.Count, oneLine(reason.Reason))
	}
	if len(reasons) > len(shown) {
		fmt.Fprintf(writer, "  ... and %d more\n", len(reasons)-len(shown))
	}
	fmt.Fprintln(writer)
}

func oneLine(text string) string {
	text = strings.ReplaceAll(text, "\n", " ")
	if len(text) > 160 {
		return text[:160] + "..."
	}
	return text
}

prelude.go:
package main

// prelude is the harness test262's assert.js and sta.js provide, rewritten so stage 0 can lower it.
// harness/compareArray.js is empty upstream: compareArray lives in assert.js, and tests that list
// compareArray.js still call it.
//
// What was adapted, and why:
//
//   - assert, assert.sameValue, assert.notSameValue, assert.throws, assert.compareArray and
//     assert._isSameValue are free functions (assert, assertSameValue, ...). 0.1 refuses expandos,
//     so a function cannot carry properties. rewriteHarnessCalls renames the calls in the test body.
//     Both Node and the native binary run that one rewritten program.
//   - SameValue covers string, number (NaN equals NaN, and -0 is not 0), boolean and undefined.
//     Anything else is not a member of that union, so the checker refuses the call instead of the
//     runner comparing it wrong.
//   - assert.throws is assertThrows(name, fn). It checks that an Error was caught, not that the
//     constructor is the one named: stage 0 only builds `new Error`, and only `instanceof Error`
//     on a catch lowers. The name is what the failure says when nothing was thrown. This is weaker
//     than the harness, on both sides equally. A library call that throws on Node panics natively
//     (docs/0.1.md), and a panic is not caught, so those tests come out fail rather than pass.
//   - compareArray is generic over string, number or boolean. An array of a union does not lower;
//     one copy per element type does. SameValue is the element comparison, as in assert.js.
//   - Test262Error is a class with a message, not a prototype assignment. `throw new Test262Error`
//     is still refused (only `throw new Error` lowers). $DONOTEVALUATE throws an Error.
//   - "use strict" directives are dropped. Every Adamic file is a module, and a string used as a
//     statement does not lower.
const prelude = `class Test262Error {
	message: string;
	constructor(message?: string) {
		this.message = message ?? "";
	}
	toString(): string {
		return "Test262Error: " + this.message;
	}
}

function $DONOTEVALUATE(): void {
	throw new Error("Test262: This statement should not be evaluated.");
}

function sameValue(left: string | number | boolean | undefined, right: string | number | boolean | undefined): boolean {
	if (typeof left === "number" && typeof right === "number") {
		if (Number.isNaN(left) && Number.isNaN(right)) {
			return true;
		}
		if (left === 0 && right === 0) {
			return 1 / left === 1 / right;
		}
		return left === right;
	}
	if (typeof left === "string" && typeof right === "string") {
		return left === right;
	}
	if (typeof left === "boolean" && typeof right === "boolean") {
		return left === right;
	}
	return left === undefined && right === undefined;
}

function assert(mustBeTrue: boolean, message?: string): void {
	if (mustBeTrue === true) {
		return;
	}
	throw new Error(message ?? "Expected true but got a non-true value");
}

function assertSameValue(actual: string | number | boolean | undefined, expected: string | number | boolean | undefined, message?: string): void {
	if (sameValue(actual, expected)) {
		return;
	}
	throw new Error(message ?? "Expected SameValue");
}

function assertNotSameValue(actual: string | number | boolean | undefined, unexpected: string | number | boolean | undefined, message?: string): void {
	if (!sameValue(actual, unexpected)) {
		return;
	}
	throw new Error(message ?? "Expected NotSameValue");
}

function assertIsSameValue(left: string | number | boolean | undefined, right: string | number | boolean | undefined): boolean {
	return sameValue(left, right);
}

function compareArray<T extends string | number | boolean>(actual: readonly T[], expected: readonly T[]): boolean {
	if (actual.length !== expected.length) {
		return false;
	}
	for (let index = 0; index < actual.length; index += 1) {
		if (!sameValue(actual[index], expected[index])) {
			return false;
		}
	}
	return true;
}

function assertCompareArray<T extends string | number | boolean>(actual: readonly T[], expected: readonly T[], message?: string): void {
	if (compareArray(actual, expected)) {
		return;
	}
	throw new Error(message ?? "arrays differ");
}

function assertThrows(expectedName: string, func: () => void, message?: string): void {
	let threw = false;
	try {
		func();
	} catch (caught) {
		threw = true;
		if (!(caught instanceof Error)) {
			throw new Error((message ?? "") + "thrown value was not an Error");
		}
	}
	if (!threw) {
		throw new Error((message ?? "") + "Expected " + expectedName + " to be thrown but no exception was thrown at all");
	}
}
`

// program is one Adamic source: the adapted harness, then the test with its frontmatter removed and
// its harness calls rewritten. Node runs the same text as a module (.mts); adamic reads it as .ts.
func program(testBody string) string {
	return prelude + "\n" + stripUseStrict(testBody)
}

profile.go:
package main

import (
	"encoding/json"
	"os"
	"sort"
	"sync"
	"time"
)

// Profiling is opt in and written separately from verdicts and ordered progress.
// Offsets share a monotonic origin, so overlapping workers can be inspected directly.
type runProfile struct {
	origin  time.Time
	mutex   sync.Mutex
	Tests   []*testProfile `json:"tests"`
	Prepare []phaseProfile `json:"prepare"`
}
type testProfile struct {
	Path   string         `json:"path"`
	Worker int            `json:"worker"`
	Start  float64        `json:"start"`
	End    float64        `json:"end"`
	Phases []phaseProfile `json:"phases"`
	owner  *runProfile
}
type phaseProfile struct {
	Stage string  `json:"stage"`
	Start float64 `json:"start"`
	End   float64 `json:"end"`
	Hit   bool    `json:"hit,omitempty"`
}

func newRunProfile() *runProfile      { return &runProfile{origin: time.Now()} }
func (p *runProfile) offset() float64 { return time.Since(p.origin).Seconds() }
func (p *runProfile) preparing(stage string) func() {
	if p == nil {
		return func() {}
	}
	start := p.offset()
	return func() { p.Prepare = append(p.Prepare, phaseProfile{Stage: stage, Start: start, End: p.offset()}) }
}
func (p *runProfile) begin(path string, worker int) *testProfile {
	if p == nil {
		return nil
	}
	return &testProfile{Path: path, Worker: worker, Start: p.offset(), owner: p}
}
func (p *testProfile) finish() {
	if p == nil {
		return
	}
	p.End = p.owner.offset()
	p.owner.mutex.Lock()
	p.owner.Tests = append(p.owner.Tests, p)
	p.owner.mutex.Unlock()
}
func (p *testProfile) command(stage string, execute func() execution) execution {
	if p == nil {
		return execute()
	}
	start := p.owner.offset()
	result := execute()
	p.Phases = append(p.Phases, phaseProfile{Stage: stage, Start: start, End: p.owner.offset()})
	return result
}
func (p *testProfile) observation(stage string, cache *resultCache, key string, execute func() (execution, bool)) execution {
	if p == nil {
		return cache.observe(key, execute)
	}
	start := p.owner.offset()
	hit := true
	result := cache.observe(key, func() (execution, bool) { hit = false; return execute() })
	p.Phases = append(p.Phases, phaseProfile{Stage: stage, Start: start, End: p.owner.offset(), Hit: hit})
	return result
}
func (p *runProfile) write(path string) error {
	sort.Slice(p.Tests, func(i, j int) bool { return p.Tests[i].Path < p.Tests[j].Path })
	data, err := json.MarshalIndent(p, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(path, append(data, '\n'), 0600)
}

reason.go:
package main

import (
	"regexp"
	"strings"
)

// cmd/adamic-meter is not on main. The fuzzer (internal/fuzz/run.go, compilerRefusal) already splits
// a compiler failure into "not yet", a 0.1 refusal, a checker diagnostic, or a crash. The meter
// counts those across thousands of files, so the location is stripped and the fix after a refusal's
// semicolon is dropped: two tests that refuse `var` are one reason, not two paths. Checker
// messages keep their TS code, with quoted names collapsed, so `Cannot find name 'x'` and
// `Cannot find name 'y'` are one reason.
//
//	adamic: prog.ts:1:1: stage 0 can't lower a rest parameter yet
//	  -> not yet: a rest parameter
//	adamic: prog.ts:1:1: Adamic 0.1 refuses var; use const or let
//	  -> refuses var
//	prog.ts:1:12: error TS7006: Parameter 'x' implicitly has an 'any' type.
//	  -> error TS7006: Parameter '…' implicitly has an 'any' type.

var locationPrefix = regexp.MustCompile(`^(?:adamic:\s+)?(?:(?:[A-Za-z]:)?[^:\n]+?:\d+:\d+:\s+)+`)
var quotedSpan = regexp.MustCompile(`'[^']*'|"[^"]*"`)

// normalizeReason collapses the first diagnostic line to a reason that groups across files.
func normalizeReason(stderr string) string {
	line := firstLine(stderr)
	line = strings.TrimSpace(line)
	for {
		stripped := locationPrefix.ReplaceAllString(line, "")
		if stripped == line {
			break
		}
		line = strings.TrimSpace(stripped)
	}
	line = strings.TrimPrefix(line, "adamic: ")
	line = strings.TrimSpace(line)
	if index := strings.Index(line, "can't lower "); index >= 0 && strings.Contains(line, "yet") {
		what := strings.TrimSpace(line[index+len("can't lower "):])
		what = strings.TrimSuffix(what, "yet")
		what = strings.TrimSpace(what)
		return "not yet: " + what
	}
	const refuses = "Adamic 0.1 refuses "
	if index := strings.Index(line, refuses); index >= 0 {
		what := strings.TrimSpace(line[index+len(refuses):])
		if semi := strings.Index(what, ";"); semi >= 0 {
			what = strings.TrimSpace(what[:semi])
		}
		return "refuses " + what
	}
	if index := strings.Index(line, "error TS"); index >= 0 {
		message := line[index:]
		return quotedSpan.ReplaceAllString(message, "'…'")
	}
	if line == "" {
		return "compiler failed"
	}
	return line
}

func firstLine(text string) string {
	if index := strings.IndexAny(text, "\r\n"); index >= 0 {
		return text[:index]
	}
	return text
}

// compileClass is what `adamic c` came to. An empty kind means the C was produced. "refused" is a
// checker diagnostic, a 0.1 refusal, or a not-yet, which the meter counts together under refused.
// Anything else (a timeout, a panic, a message that isn't one of those) is a crash: the compiler
// did not refuse the program, it failed.
func compileClass(stderr string, exitCode int, timedOut bool) (kind string, reason string) {
	if timedOut {
		return "crashed", "compiler timed out"
	}
	if exitCode == 0 {
		return "", ""
	}
	text := stderr
	switch {
	case strings.Contains(text, "can't lower") && strings.Contains(text, "yet"):
		return "refused", normalizeReason(text)
	case strings.Contains(text, "Adamic 0.1 refuses"):
		return "refused", normalizeReason(text)
	case strings.Contains(text, "error TS"):
		return "refused", normalizeReason(text)
	case strings.Contains(text, "goroutine ") || strings.Contains(text, "panic:"):
		return "crashed", "compiler panicked"
	default:
		return "crashed", normalizeReason(text)
	}
}

rewrite.go:
package main

import (
	"strings"
	"unicode"
	"unicode/utf8"
)

// harnessCalls are the assert.js property calls, longest first so notSameValue is not read as
// sameValue. assert.throws is handled apart: its first argument, a constructor, becomes the name
// assertThrows takes.
var harnessCalls = []struct {
	from string
	to   string
}{
	{"assert.notSameValue", "assertNotSameValue"},
	{"assert.compareArray", "assertCompareArray"},
	{"assert._isSameValue", "assertIsSameValue"},
	{"assert.sameValue", "assertSameValue"},
}

// rewriteHarnessCalls renames harness property calls in code, leaving strings and comments alone.
// assert.throws(TypeError, fn) becomes assertThrows("TypeError", fn). A first argument that isn't a
// plain name (or a dotted name) is left as written, and the checker then refuses the call.
func rewriteHarnessCalls(source string) string {
	var builder strings.Builder
	builder.Grow(len(source))
	for index := 0; index < len(source); {
		if source[index] == '/' && index+1 < len(source) && source[index+1] == '/' {
			end := strings.IndexByte(source[index:], '\n')
			if end < 0 {
				builder.WriteString(source[index:])
				break
			}
			builder.WriteString(source[index : index+end+1])
			index += end + 1
			continue
		}
		if source[index] == '/' && index+1 < len(source) && source[index+1] == '*' {
			end := strings.Index(source[index+2:], "*/")
			if end < 0 {
				builder.WriteString(source[index:])
				break
			}
			builder.WriteString(source[index : index+2+end+2])
			index += 2 + end + 2
			continue
		}
		if source[index] == '\'' || source[index] == '"' {
			end := endOfString(source, index)
			builder.WriteString(source[index:end])
			index = end
			continue
		}
		if source[index] == '`' {
			index = writeTemplate(&builder, source, index)
			continue
		}
		if !identifierBoundary(source, index) {
			builder.WriteByte(source[index])
			index++
			continue
		}
		if strings.HasPrefix(source[index:], "assert.throws") && identifierEnded(source, index+len("assert.throws")) {
			index = writeAssertThrows(&builder, source, index)
			continue
		}
		replaced := false
		for _, call := range harnessCalls {
			if strings.HasPrefix(source[index:], call.from) && identifierEnded(source, index+len(call.from)) {
				builder.WriteString(call.to)
				index += len(call.from)
				replaced = true
				break
			}
		}
		if replaced {
			continue
		}
		builder.WriteByte(source[index])
		index++
	}
	return builder.String()
}

// writeAssertThrows copies assert.throws(...) with the callee renamed and a name-like first
// argument quoted. It returns the index just after the first argument, or after the callee if the
// argument isn't a name.
func writeAssertThrows(builder *strings.Builder, source string, index int) int {
	builder.WriteString("assertThrows")
	index += len("assert.throws")
	for index < len(source) && isSpace(source[index]) {
		builder.WriteByte(source[index])
		index++
	}
	if index >= len(source) || source[index] != '(' {
		return index
	}
	builder.WriteByte('(')
	index++
	argumentStart := index
	for index < len(source) && isSpace(source[index]) {
		index++
	}
	name, next := constructorName(source, index)
	if name == "" {
		return argumentStart
	}
	for cursor := argumentStart; cursor < index; cursor++ {
		builder.WriteByte(source[cursor])
	}
	builder.WriteByte('"')
	builder.WriteString(name)
	builder.WriteByte('"')
	return next
}

// constructorName is TypeError or foo.Bar at index, and the index after it. Empty if the text
// there isn't a dotted name.
func constructorName(source string, index int) (string, int) {
	start := index
	if index >= len(source) || !isIdentifierStart(rune(source[index])) {
		return "", index
	}
	index++
	for index < len(source) {
		character := rune(source[index])
		if isIdentifierPart(character) {
			index++
			continue
		}
		if source[index] == '.' && index+1 < len(source) && isIdentifierStart(rune(source[index+1])) {
			index++
			continue
		}
		break
	}
	return source[start:index], index
}

func identifierBoundary(source string, index int) bool {
	if index == 0 {
		return true
	}
	previous, _ := utf8.DecodeLastRuneInString(source[:index])
	return !isIdentifierPart(previous)
}

func identifierEnded(source string, index int) bool {
	if index >= len(source) {
		return true
	}
	next, _ := utf8.DecodeRuneInString(source[index:])
	return !isIdentifierPart(next)
}

func isIdentifierStart(character rune) bool {
	return character == '$' || character == '_' || unicode.IsLetter(character)
}

func isIdentifierPart(character rune) bool {
	return isIdentifierStart(character) || unicode.IsDigit(character)
}

func isSpace(character byte) bool {
	return character == ' ' || character == '\t' || character == '\n' || character == '\r'
}

func endOfString(source string, index int) int {
	quote := source[index]
	index++
	for index < len(source) {
		if source[index] == '\\' && index+1 < len(source) {
			index += 2
			continue
		}
		if source[index] == quote {
			return index + 1
		}
		if quote != '`' && source[index] == '\n' {
			return index
		}
		index++
	}
	return index
}

// writeTemplate copies a template literal, rewriting harness calls inside each ${ } expression.
func writeTemplate(builder *strings.Builder, source string, index int) int {
	builder.WriteByte('`')
	index++
	for index < len(source) {
		if source[index] == '\\' && index+1 < len(source) {
			builder.WriteString(source[index : index+2])
			index += 2
			continue
		}
		if source[index] == '`' {
			builder.WriteByte('`')
			return index + 1
		}
		if source[index] == '$' && index+1 < len(source) && source[index+1] == '{' {
			expression, next, ok := expressionInside(source, index+2, 1)
			if !ok {
				builder.WriteString(source[index:])
				return len(source)
			}
			builder.WriteString("${")
			builder.WriteString(rewriteHarnessCalls(expression))
			builder.WriteByte('}')
			index = next
			continue
		}
		builder.WriteByte(source[index])
		index++
	}
	return index
}

// expressionInside is the source of a ${ } expression starting at index, already inside one brace,
// and the index just after its closing brace.
func expressionInside(source string, index int, depth int) (string, int, bool) {
	start := index
	for index < len(source) && depth > 0 {
		if source[index] == '\\' && index+1 < len(source) {
			index += 2
			continue
		}
		if source[index] == '\'' || source[index] == '"' || source[index] == '`' {
			index = endOfQuoted(source, index)
			continue
		}
		if source[index] == '{' {
			depth++
		} else if source[index] == '}' {
			depth--
			if depth == 0 {
				return source[start:index], index + 1, true
			}
		}
		index++
	}
	return "", start, false
}

func endOfQuoted(source string, index int) int {
	if source[index] == '`' {
		index++
		for index < len(source) {
			if source[index] == '\\' && index+1 < len(source) {
				index += 2
				continue
			}
			if source[index] == '`' {
				return index + 1
			}
			if source[index] == '$' && index+1 < len(source) && source[index+1] == '{' {
				_, next, ok := expressionInside(source, index+2, 1)
				if !ok {
					return len(source)
				}
				index = next
				continue
			}
			index++
		}
		return index
	}
	return endOfString(source, index)
}

// stripUseStrict drops directive lines. A module is already strict, and stage 0 can't lower a
// string used as a statement, so leaving the directive in would refuse every test that carries one.
func stripUseStrict(source string) string {
	var builder strings.Builder
	for _, line := range strings.Split(source, "\n") {
		trim := strings.TrimSpace(line)
		if trim == `"use strict";` || trim == `'use strict';` || trim == `"use strict"` || trim == `'use strict'` {
			continue
		}
		builder.WriteString(line)
		builder.WriteByte('\n')
	}
	return builder.String()
}

// codeOnly is the source with comments and strings blanked, so a feature scan doesn't fire on a
// comment that mentions eval or Symbol. Newlines stay, so positions aren't required.
func codeOnly(source string) string {
	var builder strings.Builder
	builder.Grow(len(source))
	for index := 0; index < len(source); {
		if source[index] == '/' && index+1 < len(source) && (source[index+1] == '/' || source[index+1] == '*') {
			if source[index+1] == '/' {
				end := strings.IndexByte(source[index:], '\n')
				if end < 0 {
					break
				}
				builder.WriteByte('\n')
				index += end + 1
				continue
			}
			end := strings.Index(source[index+2:], "*/")
			if end < 0 {
				break
			}
			chunk := source[index : index+2+end+2]
			builder.WriteString(strings.Repeat("\n", strings.Count(chunk, "\n")))
			index += 2 + end + 2
			continue
		}
		if source[index] == '\'' || source[index] == '"' || source[index] == '`' {
			end := endOfQuoted(source, index)
			chunk := source[index:end]
			builder.WriteString(strings.Repeat("\n", strings.Count(chunk, "\n")))
			index = end
			continue
		}
		builder.WriteByte(source[index])
		index++
	}
	return builder.String()
}

run.go:
package main

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"sync"
	"syscall"
	"time"

	"github.com/system-inc/adamic/internal/native"
)

// engine owns one checkout's compiler, keyed runtime archive and observation cache. Each worker
// owns a compiler process; tests are classified and their observations reduced in serial order.
type engine struct {
	test262          string
	work             string
	adamic           string
	runtime          []string
	include          string
	flags            []string
	log              io.Writer
	adapt            bool
	jobs             int
	runtimeKey       string
	cache            *resultCache
	nodeVersion      string
	context          string
	nodeContext      string
	compiler         *compilerWorker
	inProcess        bool
	compilerIdentity string
	profile          *runProfile
	worker           int
	root             string
	fallback         *compilerFallback
}

func prepare(root string, test262 string, work string) (*engine, error) {
	return prepareMode(root, test262, work, nil, false)
}

func prepareProfile(root string, test262 string, work string, profile *runProfile) (*engine, error) {
	return prepareMode(root, test262, work, profile, false)
}

func prepareMode(root string, test262 string, work string, profile *runProfile, inProcess bool) (*engine, error) {
	done := profile.preparing("go-build")
	if err := os.MkdirAll(work, 0o755); err != nil {
		return nil, err
	}
	adamic := filepath.Join(work, "adamic")
	if !inProcess {
		build := exec.Command("go", "build", "-o", adamic, "./cmd/adamic")
		build.Dir = root
		if output, err := build.CombinedOutput(); err != nil {
			return nil, fmt.Errorf("building adamic: %w\n%s", err, output)
		}
	}
	done()
	done = profile.preparing("runtime-library")
	include := filepath.Join(root, "internal", "native", "runtime")
	// Sanitizers, as the oracle compiles: a native memory bug is a crash, not a pass. Leaks are not
	// compared to Node (the process exits either way), so leak detection stays off at run time.
	flags := native.Flags(native.Options{Sanitize: true})
	library, err := native.RuntimeLibrary(include, native.Options{Sanitize: true})
	if err != nil {
		return nil, err
	}
	done()
	done = profile.preparing("cache-context")
	identityPath := adamic
	if inProcess {
		identityPath, err = os.Executable()
		if err != nil {
			return nil, err
		}
	}
	compilerBytes, err := os.ReadFile(identityPath)
	if err != nil {
		return nil, err
	}
	cache, version, context, err := prepareCache()
	if err != nil {
		return nil, err
	}
	sourceIdentity, err := loweringSourceIdentity(root)
	if err != nil {
		return nil, err
	}
	context = cacheKey(context, sourceIdentity)
	done()
	return &engine{
		profile: profile,
		root:    root, fallback: &compilerFallback{}, inProcess: inProcess,
		test262:          test262,
		work:             work,
		adamic:           adamic,
		runtime:          native.RuntimeLinkFlags(library),
		runtimeKey:       filepath.Base(filepath.Dir(library)),
		compilerIdentity: cacheKey(string(compilerBytes)),
		cache:            cache, nodeVersion: version, context: context, nodeContext: cache.nodeContext,
		include: filepath.Dir(library),
		flags:   flags,
		log:     os.Stderr,
	}, nil
}

// result is one test after it has been classified and, if attempted, run.
type result struct {
	Path        string         `json:"path"`
	Directory   string         `json:"directory"`
	Kind        outcomeKind    `json:"kind"`
	Reason      string         `json:"reason,omitempty"`
	Adaptations map[string]int `json:"adaptations,omitempty"`
}

func (e *engine) runFilter(filter string, limit int, classifyOnly bool) (filterReport, error) {
	files, err := listTests(e.test262, filter)
	if err != nil {
		return filterReport{}, err
	}
	report := filterReport{Path: filter}
	attempted := 0
	tests := make([]classified, len(files))
	results := make([]result, len(files))
	ready := make([]chan struct{}, len(files))
	indices := make([]int, 0, len(files))
	for index, file := range files {
		source, err := os.ReadFile(file)
		if err != nil {
			return report, err
		}
		relative, err := filepath.Rel(filepath.Join(e.test262, "test"), file)
		if err != nil {
			relative = file
		}
		relative = filepath.ToSlash(relative)
		test := classify(relative, string(source), e.adapt)
		tests[index] = test
		ready[index] = make(chan struct{})
		if test.Skip != "" {
			results[index] = result{Path: relative, Directory: test.Directory, Kind: outcomeSkipped, Reason: test.Skip}
			close(ready[index])
		} else if classifyOnly || (limit > 0 && attempted >= limit) {
			results[index] = result{Path: relative, Directory: test.Directory, Kind: outcomeUnrun, Reason: "not run"}
			close(ready[index])
		} else {
			attempted++
			indices = append(indices, index)
		}
	}
	jobs := e.jobs
	if jobs < 1 {
		jobs = 1
	}
	if jobs > len(indices) {
		jobs = len(indices)
	}
	if jobs > 1 {
		sort.SliceStable(indices, func(i, j int) bool { return len(tests[indices[i]].Program) > len(tests[indices[j]].Program) })
	}
	queue := make(chan int)
	var workers sync.WaitGroup
	locals := make([]engine, jobs)
	for worker := 0; worker < jobs; worker++ {
		local := *e
		local.worker = worker
		// Preserve the serial artifact path when there is just one worker.
		if jobs > 1 {
			local.work = filepath.Join(e.work, fmt.Sprintf("worker-%d", worker))
			if err := os.MkdirAll(local.work, 0755); err != nil {
				return report, err
			}
		}
		locals[worker] = local
	}
	for worker := range locals {
		local := locals[worker]
		workers.Go(func() {
			if local.inProcess {
				local.compiler = &compilerWorker{}
				defer local.compiler.close()
			}
			for index := range queue {
				one := local.attempt(tests[index])
				if one.Kind == outcomeCrashed {
					one.Reason = withCrashPath(one.Path, one.Reason)
				}
				results[index] = one
				close(ready[index])
			}
		})
	}
	go func() {
		for _, index := range indices {
			queue <- index
		}
		close(queue)
	}()
	for index := range files {
		<-ready[index]
		report.add(results[index])
		if (index+1)%50 == 0 || index+1 == len(files) {
			fmt.Fprintf(e.log, "%s %d/%d pass=%d fail=%d refused=%d crashed=%d skipped=%d\n",
				filter, index+1, len(files), report.Pass, report.Fail, report.Refused, report.Crashed, report.Skipped)
		}
	}
	workers.Wait()
	report.finish()
	return report, nil
}

// Stable paths are part of both execution commands, not omitted from their keys. The lock
// keeps concurrent invocations from overwriting a program while another invocation runs it.
func (e *engine) programDirectory(test classified) string {
	if e.cache == nil {
		return e.work
	}
	return filepath.Join(e.cache.directory, "programs", cacheKey(test.Program, e.nodeContext))
}

func (e *engine) attempt(test classified) result {
	profile := e.profile.begin(test.Path, e.worker)
	defer profile.finish()
	base := result{Path: test.Path, Directory: test.Directory, Adaptations: test.Adaptations}
	directory := e.programDirectory(test)
	if err := os.MkdirAll(directory, 0700); err != nil {
		// A broken observation cache must not prevent the uncached program from running.
		directory = e.work
		if err := os.MkdirAll(directory, 0700); err != nil {
			base.Kind = outcomeCrashed
			base.Reason = err.Error()
			return base
		}
	}
	lock, err := os.OpenFile(filepath.Join(directory, ".lock"), os.O_CREATE|os.O_RDWR, 0600)
	if err != nil && directory != e.work {
		directory = e.work
		lock, err = os.OpenFile(filepath.Join(directory, ".lock"), os.O_CREATE|os.O_RDWR, 0600)
	}
	if err != nil {
		base.Kind = outcomeCrashed
		base.Reason = err.Error()
		return base
	}
	defer lock.Close()
	if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX); err != nil {
		base.Kind = outcomeCrashed
		base.Reason = err.Error()
		return base
	}
	defer syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
	typescript := filepath.Join(directory, "program.a")
	module := filepath.Join(directory, "program.mts")
	if err := os.WriteFile(typescript, []byte(test.Program), 0o644); err != nil {
		return result{Path: test.Path, Directory: test.Directory, Kind: outcomeCrashed, Reason: err.Error()}
	}
	if err := os.WriteFile(module, []byte(test.Program), 0o644); err != nil {
		return result{Path: test.Path, Directory: test.Directory, Kind: outcomeCrashed, Reason: err.Error()}
	}
	cache := e.cache
	if dependentProgram(test.Program) {
		cache = nil
	}
	compilerCommand := cacheKey("adamic c", e.adamic, typescript, "2m", "16MiB")
	if e.compiler != nil {
		// The worker executes this runner, not the scratch copy of adamic used for fallback.
		// Its exact executable and protocol are already part of the runner context.
		compilerCommand = cacheKey("runner --compiler-worker", typescript, "2m", "16MiB")
	}
	compilerKey := compilerResultKey(test.Program, e.compilerIdentity, compilerCommand, e.context)
	lowered := profile.observation("compile", cache, compilerKey, func() (execution, bool) {
		var result execution
		if e.compiler != nil {
			result = e.compiler.compile(typescript)
			if result.Exit == -1 && !result.TimedOut {
				result = e.fallbackCompile(typescript)
			}
		} else {
			result = runCommandWithLimit(2*time.Minute, nil, 16<<20, e.adamic, "c", typescript)
		}
		// Refusals, compiler crashes and deadlines are always retried.
		return result, result.Exit == 0 && !result.TimedOut
	})
	kind, reason := compileClass(lowered.Stderr, lowered.Exit, lowered.TimedOut)
	if kind == "refused" {
		base.Kind = outcomeRefused
		base.Reason = reason
		return base
	}
	if kind == "crashed" || lowered.Exit != 0 {
		base.Kind = outcomeCrashed
		base.Reason = reason
		return base
	}
	cPath := filepath.Join(directory, "program.c")
	if err := os.WriteFile(cPath, []byte(lowered.Stdout), 0o644); err != nil {
		base.Kind = outcomeCrashed
		base.Reason = err.Error()
		return base
	}
	binary := filepath.Join(directory, "program.bin")
	arguments := append(append([]string{}, e.flags...), "-I", e.include, "-o", binary, cPath)
	arguments = append(arguments, e.runtime...)
	arguments = append(arguments, "-lm")
	nativeCommand := cacheKey(cacheKey(arguments...), binary, "15s-cpu", "2m-wall", fmt.Sprint(outputLimit), fmt.Sprint(nativeEnvironment))
	key := nativeResultKey(lowered.Stdout, e.runtimeKey, nativeCommand, e.context)
	linkFailed := false
	// Imported modules can read files or have mutable dependencies. Until their whole input
	// graph is keyed, all their observations run fresh.
	nativeRun := profile.observation("native-observation", cache, key, func() (execution, bool) {
		linked := profile.command("clang", func() execution { return runCommand(2*time.Minute, nil, "clang", arguments...) })
		if linked.Exit != 0 || linked.TimedOut {
			linkFailed = true
			return linked, false
		}
		defer os.Remove(binary)
		return profile.command("native", func() execution { return runProgram(15*time.Second, nativeEnvironment, binary) }), true
	})
	// A link failure is a compiler crash rather than a native execution verdict.
	// Only successful links publish observations, so a hit always holds a real execution.
	// Link stderr has the same classification as the original runner.
	if linkFailed {
		base.Kind = outcomeCrashed
		base.Reason = "clang: " + firstLine(nativeRun.Stderr)
		return base
	}
	nodeCommand := cacheKey("node", "--disable-warning=ExperimentalWarning", module, "15s-cpu", "2m-wall", fmt.Sprint(outputLimit))
	nodeKey := nodeResultKey(test.Program, e.nodeVersion, fmt.Sprint(e.adapt), nodeCommand, e.nodeContext)
	nodeRun := profile.observation("node", cache, nodeKey, func() (execution, bool) {
		return runProgram(15*time.Second, nil, "node", "--disable-warning=ExperimentalWarning", module), true
	})
	decided := decide(verdictInput{
		NegativePhase: test.NegativePhase,
		NegativeType:  test.NegativeType,
		Node:          nodeRun,
		Native:        nativeRun,
	})
	base.Kind = decided.Kind
	base.Reason = decided.Reason
	return base
}

var importedProgram = regexp.MustCompile(`(?:^|[^\w$])import(?:[^\w$]|$)`)
var referencedProgram = regexp.MustCompile(`(?m)^\s*///\s*<reference\b`)

func dependentProgram(program string) bool {
	return importedProgram.MatchString(codeOnly(program)) || referencedProgram.MatchString(program)
}

var nativeEnvironment = []string{
	"ASAN_OPTIONS=detect_leaks=0:abort_on_error=1:halt_on_error=1",
	"UBSAN_OPTIONS=halt_on_error=1:abort_on_error=1",
}

const outputLimit = 256 << 10

// Test programs get a CPU budget; time waiting for a core does not spend it.
// Keep a wall-clock backstop for programs that block without consuming CPU.
func runProgram(cpuLimit time.Duration, extra []string, name string, args ...string) execution {
	seconds := int64((cpuLimit + time.Second - 1) / time.Second)
	// Set only the soft limit so the kernel delivers SIGXCPU, not SIGKILL.
	wrapper := fmt.Sprintf(`ulimit -S -t %d || exit; exec "$0" "$@"`, seconds)
	arguments := append([]string{"-c", wrapper, name}, args...)
	return runCommand(2*time.Minute, extra, "/bin/sh", arguments...)
}

func runCommand(timeout time.Duration, extra []string, name string, args ...string) execution {
	return runCommandWithLimit(timeout, extra, outputLimit, name, args...)
}

// Generated C is an artifact, not program output: give it room, and never compile a truncated one.
func runCommandWithLimit(timeout time.Duration, extra []string, limit int, name string, args ...string) execution {
	ctx, cancel := context.WithTimeout(context.Background(), timeout)
	defer cancel()
	command := exec.CommandContext(ctx, name, args...)
	command.Env = append(os.Environ(), extra...)
	command.WaitDelay = 2 * time.Second
	var stdout, stderr limitedBuffer
	stdout.limit = limit
	stderr.limit = limit
	command.Stdout = &stdout
	command.Stderr = &stderr
	err := command.Run()
	result := execution{Stdout: stdout.String(), Stderr: stderr.String()}
	if stdout.exceeded || stderr.exceeded {
		result.Exit = -1
		result.Stderr = "command output exceeded capture limit\n"
		return result
	}
	if ctx.Err() == context.DeadlineExceeded {
		result.TimedOut = true
		result.Exit = -1
		return result
	}
	if err == nil {
		return result
	}
	exit, isExit := err.(*exec.ExitError)
	if !isExit {
		result.Exit = -1
		result.Stderr = result.Stderr + err.Error()
		return result
	}
	if status, ok := exit.Sys().(syscall.WaitStatus); ok {
		if status.Signaled() {
			if status.Signal() == syscall.SIGXCPU {
				result.TimedOut = true
				result.Exit = -1
				return result
			}
			result.Signal = status.Signal().String()
			result.Exit = -1
			return result
		}
		result.Exit = status.ExitStatus()
		return result
	}
	result.Exit = exit.ExitCode()
	return result
}

// limitedBuffer keeps the start of a stream and drops the rest, so a test that prints without end
// cannot fill memory before its timeout.
type limitedBuffer struct {
	buf      bytes.Buffer
	limit    int
	exceeded bool
}

func (buffer *limitedBuffer) Write(data []byte) (int, error) {
	written := len(data)
	room := buffer.limit - buffer.buf.Len()
	if written > room {
		buffer.exceeded = true
	}
	if room > 0 {
		if len(data) > room {
			data = data[:room]
		}
		_, _ = buffer.buf.Write(data)
	}
	return written, nil
}

func (buffer *limitedBuffer) String() string { return buffer.buf.String() }

func listTests(test262 string, filter string) ([]string, error) {
	root := filepath.Join(test262, "test")
	target := root
	if filter != "" {
		target = filepath.Join(root, filepath.FromSlash(filter))
	}
	info, err := os.Stat(target)
	if err != nil {
		return nil, fmt.Errorf("test262 filter %s: %w", filter, err)
	}
	if !info.IsDir() {
		return []string{target}, nil
	}
	var files []string
	err = filepath.WalkDir(target, func(path string, entry os.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if entry.IsDir() {
			return nil
		}
		name := entry.Name()
		if !strings.HasSuffix(name, ".js") || strings.Contains(name, "_FIXTURE") {
			return nil
		}
		files = append(files, path)
		return nil
	})
	if err != nil {
		return nil, err
	}
	sort.Strings(files)
	return files, nil
}

// filterReport is one directory filter's counts. Directories are the folders that hold tests.
type filterReport struct {
	Path           string        `json:"path"`
	Pass           int           `json:"pass"`
	Fail           int           `json:"fail"`
	Refused        int           `json:"refused"`
	Crashed        int           `json:"crashed"`
	Skipped        int           `json:"skipped"`
	Unrun          int           `json:"unrun,omitempty"`
	Total          int           `json:"total"`
	Directories    []dirCount    `json:"directories"`
	RefusalReasons []reasonCount `json:"refusalReasons"`
	SkipReasons    []reasonCount `json:"skipReasons"`
	CrashReasons   []reasonCount `json:"crashReasons"`
	FailReasons    []reasonCount `json:"failReasons"`
	Passes         []string      `json:"passes,omitempty"`
	Adaptations    []reasonCount `json:"adaptations,omitempty"`
	directories    map[string]*dirCount
	refusalReasons map[string]int
	skipReasons    map[string]int
	crashReasons   map[string]int
	failReasons    map[string]int
	adaptations    map[string]int
}

type dirCount struct {
	Path    string `json:"path"`
	Pass    int    `json:"pass"`
	Fail    int    `json:"fail"`
	Refused int    `json:"refused"`
	Crashed int    `json:"crashed"`
	Skipped int    `json:"skipped"`
	Unrun   int    `json:"unrun,omitempty"`
	Total   int    `json:"total"`
}

type reasonCount struct {
	Reason string `json:"reason"`
	Count  int    `json:"count"`
}

func (report *filterReport) add(one result) {
	if report.directories == nil {
		report.directories = map[string]*dirCount{}
		report.refusalReasons = map[string]int{}
		report.skipReasons = map[string]int{}
		report.crashReasons = map[string]int{}
		report.failReasons = map[string]int{}
		report.adaptations = map[string]int{}
	}
	directory := report.directories[one.Directory]
	if directory == nil {
		directory = &dirCount{Path: one.Directory}
		report.directories[one.Directory] = directory
	}
	directory.Total++
	report.Total++
	switch one.Kind {
	case outcomePass:
		report.Pass++
		directory.Pass++
		report.Passes = append(report.Passes, one.Path)
	case outcomeFail:
		report.Fail++
		directory.Fail++
		report.failReasons[one.Reason]++
	case outcomeRefused:
		report.Refused++
		directory.Refused++
		report.refusalReasons[reasonOr(one.Reason)]++
	case outcomeCrashed:
		report.Crashed++
		directory.Crashed++
		report.crashReasons[reasonOr(one.Reason)]++
	case outcomeSkipped:
		report.Skipped++
		directory.Skipped++
		report.skipReasons[reasonOr(one.Reason)]++
	case outcomeUnrun:
		report.Unrun++
		directory.Unrun++
	}
	for kind, count := range one.Adaptations {
		report.adaptations[kind] += count
	}
}

func reasonOr(reason string) string {
	if reason == "" {
		return "(no reason)"
	}
	return reason
}

func (report *filterReport) finish() {
	for _, directory := range report.directories {
		report.Directories = append(report.Directories, *directory)
	}
	sort.Slice(report.Directories, func(i int, j int) bool { return report.Directories[i].Path < report.Directories[j].Path })
	report.RefusalReasons = sortedReasons(report.refusalReasons)
	report.SkipReasons = sortedReasons(report.skipReasons)
	report.CrashReasons = sortedReasons(report.crashReasons)
	report.FailReasons = sortedReasons(report.failReasons)
	report.Adaptations = sortedReasons(report.adaptations)
	sort.Strings(report.Passes)
}

func sortedReasons(counts map[string]int) []reasonCount {
	reasons := make([]reasonCount, 0, len(counts))
	for reason, count := range counts {
		reasons = append(reasons, reasonCount{Reason: reason, Count: count})
	}
	sort.Slice(reasons, func(i int, j int) bool {
		if reasons[i].Count != reasons[j].Count {
			return reasons[i].Count > reasons[j].Count
		}
		return reasons[i].Reason < reasons[j].Reason
	})
	return reasons
}

// reportDocument is what --json prints.
type reportDocument struct {
	Test262 string         `json:"test262"`
	Commit  string         `json:"commit,omitempty"`
	Adapt   bool           `json:"adapt"`
	Filters []filterReport `json:"filters"`
}

// withCrashPath puts the test file on the crash record. The reason alone was not enough to see
// which program the compiler or clang rejected.
func withCrashPath(path string, reason string) string {
	if path == "" {
		return reason
	}
	if reason == "" {
		return path
	}
	return path + ": " + reason
}

func test262Commit(test262 string) string {
	command := exec.Command("git", "-C", test262, "rev-parse", "HEAD")
	output, err := command.Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(output))
}

func writeJSON(writer io.Writer, document reportDocument) error {
	encoded, err := json.MarshalIndent(document, "", "  ")
	if err != nil {
		return err
	}
	_, err = writer.Write(append(encoded, '\n'))
	return err
}

// The normal worker does not execute the backup compiler. Build it only if worker transport
// fails, once across all workers, so isolation still has the original diagnostic fallback.
type compilerFallback struct {
	once sync.Once
	err  error
}

func (e *engine) fallbackCompile(path string) execution {
	if e.fallback != nil && e.inProcess {
		e.fallback.once.Do(func() {
			build := exec.Command("go", "build", "-o", e.adamic, "./cmd/adamic")
			build.Dir = e.root
			if output, err := build.CombinedOutput(); err != nil {
				e.fallback.err = fmt.Errorf("building adamic: %w\n%s", err, output)
			}
		})
		if e.fallback.err != nil {
			return execution{Exit: -1, Stderr: e.fallback.err.Error()}
		}
	}
	return runCommandWithLimit(2*time.Minute, nil, 16<<20, e.adamic, "c", path)
}

verdict.go:
package main

import (
	"regexp"
	"strconv"
	"strings"
)

// Outcome is one test's result. pass is both sides succeeding with the same output, or, for a
// negative runtime test, both sides failing the way the frontmatter requires. fail is a
// disagreement, including a native failure where Node succeeded. refused is stage 0 or the checker
// declining the program. crashed is a signal, a sanitizer, a timeout, or the compiler panicking.
type outcomeKind string

const (
	outcomePass    outcomeKind = "pass"
	outcomeFail    outcomeKind = "fail"
	outcomeRefused outcomeKind = "refused"
	outcomeCrashed outcomeKind = "crashed"
	outcomeSkipped outcomeKind = "skipped"
	outcomeUnrun   outcomeKind = "unrun"
)

// execution is one run's observable result, the same shape the corpus fixtures record.
type execution struct {
	Stdout   string `json:"stdout"`
	Stderr   string `json:"stderr"`
	Exit     int    `json:"exit"`
	Signal   string `json:"signal,omitempty"`
	TimedOut bool   `json:"timedOut,omitempty"`
}

// verdictInput is everything decide needs, so a fixture can stand in for a real run.
type verdictInput struct {
	NegativePhase string    `json:"negativePhase,omitempty"`
	NegativeType  string    `json:"negativeType,omitempty"`
	Node          execution `json:"node"`
	Native        execution `json:"native"`
}

type verdict struct {
	Kind   outcomeKind
	Reason string
}

// decide compares Node and the native binary. A native failure where Node succeeded is a fail,
// never a pass: the meter is how often Adamic matches Node, and counting a native failure as a
// pass would hide every miscompile. A negative runtime expectation is not optional either. Node
// throwing the named constructor, and native also exiting non-zero with the same stdout, is a pass;
// treating that as an ordinary success (both must exit 0) marks a correct negative test as a fail.
func decide(input verdictInput) verdict {
	if crashedExecution(input.Native) || crashedExecution(input.Node) {
		return verdict{Kind: outcomeCrashed, Reason: crashReason(input)}
	}
	if input.NegativePhase == "runtime" {
		return decideNegative(input)
	}
	if input.Node.Exit == 0 && input.Native.Exit == 0 && input.Node.Stdout == input.Native.Stdout && input.Node.Stderr == input.Native.Stderr {
		return verdict{Kind: outcomePass}
	}
	return verdict{Kind: outcomeFail, Reason: disagreeReason(input)}
}

func decideNegative(input verdictInput) verdict {
	nodeThrew := input.Node.Exit != 0 && errorNamed(input.Node.Stderr, input.NegativeType)
	nativeFailed := input.Native.Exit != 0
	if nodeThrew && nativeFailed && input.Node.Stdout == input.Native.Stdout {
		return verdict{Kind: outcomePass}
	}
	reason := "negative " + input.NegativeType + " not observed"
	if input.Node.Exit == 0 {
		reason = "negative " + input.NegativeType + ": node exited 0"
	} else if !nodeThrew {
		reason = "negative " + input.NegativeType + ": node did not throw it"
	} else if input.Native.Exit == 0 {
		reason = "negative " + input.NegativeType + ": native exited 0"
	} else if input.Node.Stdout != input.Native.Stdout {
		reason = "negative " + input.NegativeType + ": stdout disagrees"
	}
	return verdict{Kind: outcomeFail, Reason: reason}
}

func errorNamed(stderr string, name string) bool {
	if name == "" {
		return false
	}
	return regexp.MustCompile(`(?:^|\b)` + regexp.QuoteMeta(name) + `\b`).MatchString(stderr)
}

func crashedExecution(run execution) bool {
	if run.TimedOut || run.Signal != "" {
		return true
	}
	text := run.Stderr
	return strings.Contains(text, "AddressSanitizer") || strings.Contains(text, "UndefinedBehaviorSanitizer") || strings.Contains(text, "runtime error:")
}

func crashReason(input verdictInput) string {
	switch {
	case input.Native.TimedOut:
		return "native timed out"
	case input.Node.TimedOut:
		return "node timed out"
	case input.Native.Signal != "":
		return "native " + input.Native.Signal
	case input.Node.Signal != "":
		return "node " + input.Node.Signal
	case crashedExecution(input.Native):
		return "native sanitizer"
	default:
		return "node sanitizer"
	}
}

func disagreeReason(input verdictInput) string {
	if input.Node.Exit == 0 && input.Native.Exit != 0 {
		return "native failed where node passed (node 0, native " + strconv.Itoa(input.Native.Exit) + ")"
	}
	if input.Node.Exit != input.Native.Exit {
		return "exit " + strconv.Itoa(input.Node.Exit) + " vs " + strconv.Itoa(input.Native.Exit)
	}
	if input.Node.Stdout != input.Native.Stdout {
		return "stdout disagrees"
	}
	return "stderr disagrees"
}
